quests[56443] = { id = 56443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanisches Auge", description = "<Während der mechanische Körper von Einheit 17 zu einem Haufen zusammenfällt, leuchtet ein Auge auf.\n\nIhr hört ein Ploppen und das Auge fliegt durch eine kleine Explosion angetrieben aus dem Kopf.\n\nIhr hebt das Auge auf und bemerkt, dass es einige Male zuckt und sich dann abschaltet.\n\nDie Bürger des Rostbolzens scheinen Schrott zu mögen, vielleicht sind sie also daran interessiert.>", sourceObjective = "Zeigt das mechanische Auge Vera Einzelrad im Rostbolzen in Mechagon.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt das von einem mechanischen Murmeltier? Muss das aus rauchgrauem Metall gewesen sein.\n\nHabe ich Euch je meine Geschichte über diese unheimliche Einheit 17 erzählt?\n\nDa war ich also und durchwühlte einen Schrotthaufen nach etwas Brauchbarem, so wie Ihr das auch macht. Plötzlich steht sie vor mir: Einheit 17.\n\nIch bin erstarrt. Hatte sie mich gesehen? Was würde sie tun? Ich machte einen Schritt zurück, sie zuckte, ich jaulte.\n\nDann brüllte sie mich in einem Ton an, den ich nie vergessen werde.\n\n\"Fehler 74.\"\n\nIch rannte zurück, so schnell meine Beine mich trugen.\n\n<Vera schaudert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56444] = { id = 56444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wackelschwänzchens Piksgabel", description = "<Die zähe Zinke des bezwungenen Prinzen.\n\nDarin ist überhaupt keine Macht zu spüren. Genau genommen scheint die Gabel ziemlich schlicht und ein bisschen rostig zu sein.\n\nIhr steckt sie trotzdem ein. Vielleicht ist Handwerker Itanu daran interessiert.>", sourceObjective = "Zeigt Wackelschwänzchens PiksgabelHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ah, da seid Ihr ja wieder, habt Ihr noch mehr Schätze aus der Tiefe?\n\nOh, ein Esswerkzeug. Von dessen Wert müsst Ihr mich erst noch überzeugen.\n\nEs stammt von einem kleinen Naga? Hm, ja. Ich habe so einen, wie Ihr ihn beschreibt, schon einmal gesehen.\n\nIch habe viele lange Stunden gegrübelt, wo er hergekommen sein könnte.\n\nIch habe beschlossen, dass es ist das Beste ist, nicht weiter darüber nachzudenken.\n\nIch nehme Euch die Gabel allerdings gerne ab. Sie wird mir helfen, die Seepocken von meinem Haus zu entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56445] = { id = 56445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wackelschwänzchens Piksgabel", description = "<Die zähe Zinke des bezwungenen Prinzen.\n\nDarin ist überhaupt keine Macht zu spüren. Genau genommen scheint die Gabel ziemlich schlicht und ein bisschen rostig zu sein.\n\nIhr steckt sie trotzdem ein. Vielleicht ist Finderin Palta daran interessiert.>", sourceObjective = "Zeigt Wackelschwänzchens PiksgabelFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Oh, hallo, wie geht's, wie steht's? Habt Ihr etwas zu verkaufen? Oder wollt Ihr etwas kaufen?\n\nEine Gabel? Ihr habt mir eine Gabel mitgebracht?\n\nVon einem winzigen Naga? Oh, ja, den hab ich schon mal gesehen. Wir reden ständig darüber! Was genau ist er eigentlich?\n\nEin Nagababy? Oder vielleicht eine Vision aus den Tiefen? Wo ist er hergekommen?\n\nIch habe keine Antworten für Euch. Aber ich nehme die Gabel... Es ist fast Zeit zum Abendessen.\n\nIch glaube, ich gönne mir ein Fischgericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56446] = { id = 56446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ledrige Giftdrüse", description = "<Ihr entreißt dem Kadaver des Schnappdrachens eine ledrige Drüse. Gift tropft aus einer Öffnung an der Seite und zischt, als es den Boden berührt. Dabei hinterlassen die Tropfen kleine Löcher.\n\nDieses Gift scheint sehr stark zu sein. Es wäre das Beste, die Giftdrüse nach Mezzameer zu bringen.>", sourceObjective = "Zeigt die ledrige GiftdrüseHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Lasst mich Euch das abnehmen, mein Freund. Man sollte nicht allzu lange mit dem Gift herumhantieren.\n\nDie Naga zähmen Schnappdrachen mit Leichtigkeit, aber für uns ist das schwieriger. Sie scheinen über eine natürliche Verbundenheit mit ihnen zu verfügen. Ich beneide sie etwas, denn diese Kreaturen sind sowohl wild als auch loyal.\n\nDas Gift, das sie speien, ist tödlich. Ich kenne nur eine, die damit meisterlich zurechtkommt: eine Nagakommandantin. Wir glauben, sie isst diese Substanz, um sich immun zu machen. Ich weiß nicht, wie das möglich ist, sie muss im Kampf eine schreckliche Gegnerin sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56447] = { id = 56447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halbverdauter Tiefenkorallensamen", description = "<Ihr untersucht diesen seltsam aggressiven Tiefenrochen und findet einige halbverdaute Kapseln.\n\nIhr habt ähnliche Kapseln schon früher an den Korallen in diesem Gebiet gesehen. Scheinbar ernähren sich die Tiefenrochen davon.\n\nDas könnte ihre merkwürdige Flugfähigkeit erklären.\n\nVielleicht weiß Handwerker Itanu mehr.>", sourceObjective = "Zeigt den halbverdauten Tiefenkorallensamen Handwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Da seid Ihr ja wieder. Seid Ihr gekommen, um Handel zu treiben?\n\nAh, ja, die Korallen bringen solche Kapseln hervor. Die Tiefenrochen haben eine Vorliebe für sie. Manchmal können wir sie damit in eine Falle locken, um sie zu zähmen oder zu verspeisen.\n\nDie Kapseln sind mit irgendeinem Gas gefüllt. Ich selbst habe noch nie gewagt, es einzuatmen, aber ich vermute, dass diese Ernährung dafür sorgt, dass die Rochen jetzt schweben können.\n\nDie Kreaturen der Tiefe sind zuvor noch nie mit Luft in Kontakt gekommen, aber so ein Ergebnis hätte auch ich nicht vorhersehen können. Es ist faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[56448] = { id = 56448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeworfener Stachelpanzer", description = "<Der abgeworfene Panzer einer besiegten Stachelkrabbe, einer bösartigen Krabbenspezies, die erstmals in Nazjatar entdeckt wurde.\n\nIhre Stacheln sind sehr scharf.\n\nHandwerker Itanu hat vielleicht Verwendung dafür.>", sourceObjective = "Zeigt den abgeworfenen Stachelpanzer Handwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Das ist ein wirklich schöner Panzer. Wir finden sie immer, wenn die Stachelkrabben ihre alten Panzer abwerfen.\n\nStachelkrabben lauern in tiefen Gräben und warten darauf, dass sie große Fische aufspießen und verschlingen können. Die Tiere in unseren Gewässern sind nicht so nett wie Eure.\n\nMit den Panzern selbst können wir nichts anfangen. Sie werden nach einer Weile dünn und brüchig.\n\nFrüher haben die Kinder sie mit Sand gefüllt und sie zur Dekoration an die Korallen gehängt.\n\nDas ist lange her.\n\n<Itanu wirft den Panzer mit einem tiefen Seufzer in den Sand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56449] = { id = 56449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irisierender Muschelpanzer", description = "<Eine großer, harter Muschelpanzer von einem bezwungenen Einsiedlerkrebs.\n\nDer Panzer war wesentlich größer als der Krebs und schillert in verschiedenen Farben, je nachdem, wie man ihn dreht.\n\nIrgendjemand in Mezzameer wird doch sicherlich an diesem hübschen Panzer Interesse haben.>", sourceObjective = "Zeigt den irisierenden Muschelpanzer Handwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Muschelpanzer eines Einsiedlerkrebses. Die Krebse hier sind nicht leicht zu jagen, aber sie sind es auch nicht wert. Die Krebse sind so klein, dass man kaum eine Mahlzeit daraus gewinnen kann.\n\nDie Muschelpanzer allerdings sind sehr nützlich. Wir benutzen sie, um Speerspitzen, Schilde und sogar Küchenutensilien und Töpfe daraus zu fertigen. Sie sind sehr vielseitig und verlieren ihre Belastbarkeit nicht im Laufe der Zeit.\n\nIch werde diesen hier zu unseren Vorräten legen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[56450] = { id = 56450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalglibber", description = "<Ihr untersucht den Kadaver des Abgrundaals, der mit einem merkwürdigen Schleim überzogen ist.\n\nDer Schleim bedeckt Eure Hände und Arme und scheint sich nur schwer wieder entfernen zu lassen.\n\nEiner Eurer Verbündeten aus der Tiefsee weiß vielleicht mehr darüber.>", sourceObjective = "Zeigt den AalglibberHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Aalglibber? Wo seid Ihr denn da hineingeraten? Aale, würde ich vermuten.\n\nKommt, lasst mich das für Euch entfernen. Wir haben vielfältige Verwendungsmöglichkeiten dafür, ob Ihr es glaubt oder nicht. Nur wenige Dinge können hier, unter den Wellen, andere Dinge schlüpfrig machen. Ihr werdet das vielleicht auch noch nützlich finden.\n\n<Itanu reibt Euch etwas Glibber auf Eure Arme und Beine.>\n\nIhr werdet jetzt wie die Gezeiten zwischen den Korallen hindurchgleiten, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[56451] = { id = 56451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gescheckte Hydraschuppe", description = "<Die Schuppe eines kürzlich bezwungenen Hydrajungen. Sie scheint vielfarbig zu sein.\n\nOffenbar gibt es unter den Hydras dieser Region einen Kampf um die Vorherrschaft. Einer Eurer neuen Verbündeten weiß vielleicht mehr.>", sourceObjective = "Zeigt die gescheckte HydraschuppeHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ah, eine Hydraschuppe. Davon haben wir einige hier in der Gegend.\n\nEs gibt drei Matriarchinnen, die ihre Rudel anführen. Jede hat im Laufe der Jahre versucht, die Herrschaft über das Gebiet an sich zu reißen, aber alle Versuche sind gescheitert.\n\nDie Naga machen sich einen Spaß daraus, Sklaven in das Gebiet zu schicken, damit sie verschlungen werden.\n\nSie sind niemandem gegenüber freundlich gesinnt, also sollten wir sie am besten in Ruhe lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56452] = { id = 56452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Organ", description = "<Ihr findet ein seltsames Organ im Leichnam des Geistbeugers. Als Ihr es aufhebt, beginnt Euer Kopf zu pulsieren.\n\nDie oktopusähnlichen Kreaturen sind eines der alten Geheimnisse Azeroths. Vielleicht kann dieses Organ etwas Licht ins Dunkel bringen.\n\nJemand in Mezzameer weiß vielleicht mehr.>", sourceObjective = "Zeigt das seltsame Organ Handwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Das Organ eines Gedankentintenfischs. Ja, die kenne ich.\n\nDie Kinder von Ozumat durchfluten die Tiefen. Es sind zu viele, um sie zu zählen.\n\nSie greifen unsere Gedanken mithilfe dieses Organs an. Es macht ein Geräusch, das direkt in Euren Geist hineinreicht.\n\nIch zeige es Euch.\n\n<Itanu drückt das Organ und Euer Geist wird von einem ohrenbetäubenden psychischen Schrei attackiert.>\n\nDie Kreatur scheint dazu geschaffen worden zu sein, den Geist zu schikanieren und den Alten zu dienen.\n\nIch werde das hier jetzt außerhalb des Lagers entsorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56453] = { id = 56453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwucherter Stein", description = "<Ein Stein von einem Erdelementar, den Ihr vor Kurzem besiegt habt. Er ist bedeckt mit Tang und diversen anderen Wasserpflanzen.\n\nIhr habt noch nicht viele dieser Kreaturen in den Tiefen gesehen. Vielleicht steckt ja etwas dahinter.\n\nEiner Eurer neuen Unterwasserverbündeten weiß vielleicht mehr.>", sourceObjective = "Zeigt den überwucherten Stein Handwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Oh, hallo, was habt Ihr denn da?\n\nEin Fragment eines tangüberwucherten Elementars? Höchst glückliche Fügung. Diese Steine können verwendet werden, um das Wachstum der meisten Pflanzensorten, die wir kennen, zu beschleunigen.\n\nWenn ich manchmal welche finde, benutze ich sie, um Heilwickel für uns wachsen zu lassen. Die Elementare selbst sind ziemlich selten.\n\nIch danke Euch für diese Spende.", sourceObjectiveStatus = "unverified-source-field" }
quests[56454] = { id = 56454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knisternde Mandibel", description = "<Die Mandibel eines Gezeitenwächters, die immer noch vor Elektrizität knistert.\n\nEiner Eurer neuen Verbündeten könnte vielleicht Verwendung dafür haben.>", sourceObjective = "Zeigt die knisternde MandibelHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Oh, damit muss ich äußerst vorsichtig umgehen. Ich möchte nicht wieder einen Stromstoß abbekommen.\n\nIhr habt also die Gezeitenwächter kennengelernt? Sie leben in den Nagahöhlen, seit ich denken kann, und dienen treu ergeben ihren Herren. Ich habe in meinem ganzen Leben bei meinen Jagdausflügen in die Wildnis noch keinen einzigen gesehen.\n\nWir können aus ihren Mandibeln viele Dinge herstellen, von Speerspitzen bis hin zu elektrifizierten Fallen. Ich werde diese hier sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56455] = { id = 56455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzyreißzahn", description = "<Ihr nehmt dem gefallenen Frenzy einen ausgewachsenen Reißzahn ab.\n\nIhr habt von einigen Seefahrern gehört, die Waffen oder Dekorationen aus Reißzähnen herstellen, die in den Tiefen gefunden wurden. Vielleicht haben Eure neuen Verbündeten Verwendung dafür?>", sourceObjective = "Zeigt den FrenzyreißzahnHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "<Itanu betrachtet den Zahn in seiner Hand.>\n\nDie Frenzys dienen niemandem außer sich selbst.\n\nIhr wisst nichts über sie.\n\n<Itanu sieht zum offenen Himmel.>\n\nHierher können sie jetzt nicht mehr kommen. Einst waren sie eine Macht, vor der sich sogar die Naga fürchteten. Selbst ihre mächtigsten Champions fürchteten sie.\n\nDas wenige Licht, das wir hatten, verlosch, wenn die Frenzys kamen. Sie waren so viele, dass sie die Sonne verdunkelten. Ihre Zähne fanden jegliches Fleisch, das nicht verborgen war.\n\nIhr werdet niemals das Entsetzen der Tiefsee kennen, Trockenwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56456] = { id = 56456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opalschnecke", description = "<Die Schnecke sackt nach Eurem Angriff zu Boden. Der Kampf scheint vorüber zu sein.\n\nSie bewegt sich nicht. Ihr beugt Euch hinunter und hebt sie auf. Dabei dreht Ihr sie instinktiv um, weil Ihr einen Angriff befürchtet.\n\nSie scheint tot, aber unbeschädigt zu sein. Ihr überlegt, die ganze Schnecke zu Euren Verbündeten in Mezzameer zu bringen.>", sourceObjective = "Zeigt die OpalschneckeHandwerker Itanu in Mezzameer in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ah, ein großartiger Fund.\n\n<Itanu nimmt Euch die Meeresschnecke ab und dreht sie um. Schneller, als Ihr sehen könnt, hat er ein kleines Messer in der Hand. Er sticht damit in das Schneckenhaus und zieht das weiche Fleisch heraus.>\n\nWunderbar! Käme sie mit Feuer in Berührung, wäre sie verdorben. Dies ist... eine Delikatesse. Die muss man genießen.\n\n<Itanu schließt seine Augen und atmet tief durch, dann schlingt er die Schnecke in einem Bissen hinunter.>\n\nHmm, mm. Schleimig und innen eigenartig rau.\n\nAusgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[56457] = { id = 56457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ledrige Giftdrüse", description = "<Ihr entreißt dem Kadaver des Schnappdrachens eine ledrige Drüse. Gift tropft aus einer Öffnung an der Seite und zischt, als es den Boden berührt. Dabei hinterlassen die Tropfen kleine Löcher.\n\nDieses Gift scheint sehr stark zu sein. Es wäre das Beste, die Giftdrüse nach Neuheim zu bringen.>", sourceObjective = "Zeigt die ledrige GiftdrüseFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ist das eine Giftdrüse in Eurer Tasche oder... warum ist die in Eurer Tasche? Ihr wisst schon, wie stark diese Dinger wirken, oder?\n\nJa, die Schnappdrachen sind uns schon lange lästig. Die Naga können sie mit ihren Gedankenspielertricks oder auch einfach nur mit Fleisch mit Leichtigkeit beeinflussen, denn sie sind keine besonders intelligenten Kreaturen. Ein paar ordentliche Mahlzeiten und sie sind so gut wie gezähmt.\n\nIch habe von einer Nagakommandantin gehört, die mit ihrem Gift im Kampf umgehen kann. Man munkelt sogar, sie würde das Zeug essen.\n\nIch hoffe, ich begegne ihr niemals!", sourceObjectiveStatus = "unverified-source-field" }
quests[56458] = { id = 56458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opalschnecke", description = "<Die Schnecke sackt nach Eurem Angriff zu Boden. Der Kampf scheint vorüber zu sein.\n\nSie bewegt sich nicht. Ihr beugt Euch hinunter und hebt sie auf. Dabei dreht Ihr sie instinktiv um, weil Ihr einen Angriff befürchtet.\n\nSie scheint tot, aber unbeschädigt zu sein. Ihr überlegt, die ganze Schnecke zu Euren Verbündeten in Neuheim zu bringen.>", sourceObjective = "Zeigt die OpalschneckeFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Oh, hallo, das ist aber eine Riesenschnecke, was? Lasst mal sehen.\n\n<Palta dreht die Schnecke um und zieht die Innereien an den Fühlern heraus.>\n\nSo ist's recht. Seht sie Euch an! Voller Schleim, komplett mit Schuppen, das wird großartig.\n\nIch werde sie zum Abendessen zubereiten, das sollte die Stimmung etwas heben. Es geht doch nichts über eine Scheibe Spindelschnecke, um an die Heimat erinnert zu werden.\n\nDanke, dass Ihr sie hergebracht habt.\n\n<Palta nickt Euch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56459] = { id = 56459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halbverdauter Tiefenkorallensamen", description = "<Ihr untersucht diesen seltsam aggressiven Tiefenrochen und findet einige halbverdaute Kapseln.\n\nIhr habt ähnliche Kapseln schon früher an den Korallen in diesem Gebiet gesehen. Scheinbar ernähren sich die Tiefenrochen davon.\n\nDas könnte ihre merkwürdige Flugfähigkeit erklären.\n\nVielleicht weiß Finderin Palta mehr.>", sourceObjective = "Zeigt den halbverdauten Tiefenkorallensamen Finderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ha, da seid Ihr ja wieder! Was ist das? Etwas, das Ihr gegessen habt?\n\nOh, ja, die Tiefenrochen lieben diese Kapseln. Sie wachsen an den Korallen in der Gegend und scheinen mit Gas gefüllt zu sein.\n\nIch dachte immer, es wäre nur Luft, aber es scheint leichter als Luft zu sein. Wenn ich eine Fischhaut mit dem Kapselinhalt fülle, schwebt sie über dem Wasser!\n\nHilft ihnen wohl irgendwie, in der Tiefe zu überleben. Ich weiß nicht so genau, wie das funktioniert, aber das Leben ist ein Mysterium, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[56460] = { id = 56460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeworfener Stachelpanzer", description = "<Der abgeworfene Panzer einer besiegten Stachelkrabbe, einer bösartigen Krabbenspezies, die erstmals in Nazjatar entdeckt wurde.\n\nIhre Stacheln sind sehr scharf.\n\nFinderin Palta hat vielleicht Verwendung dafür.>", sourceObjective = "Zeigt den abgeworfenen Stachelpanzer Finderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Der Panzer einer Stachelkrabbe? Die finden wir hier öfter in der Gegend, obwohl ich versuche, mich von den dunklen Orten fernzuhalten.\n\nDort leben sie nämlich, wisst Ihr? Die Stachelkrabben lauern in der Dunkelheit und warten auf Fische, die sie aufspießen können. Einmal habe ich gesehen, wie eine Gruppe von ihnen einen Walhai gespickt hat!\n\nWenn sie Beute verschlingen, machen sie ein zirpendes Geräusch... Ich hasse das.\n\nDie Panzer selbst sind nicht sehr nützlich. Sie werden spröde und zerbrechen leicht.\n\nSeht!\n\n<Palta wirft den Panzer gegen einen Felsen in der Nähe und er zerspringt.>\n\nJii-ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[56461] = { id = 56461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irisierender Muschelpanzer", description = "<Eine großer, harter Muschelpanzer von einem bezwungenen Einsiedlerkrebs.\n\nDer Panzer war wesentlich größer als der Krebs und schillert in verschiedenen Farben, je nachdem, wie man ihn dreht.\n\nIrgendjemand in Neuheim wird doch sicherlich an diesem hübschen Panzer Interesse haben.>", sourceObjective = "Zeigt den irisierenden Muschelpanzer Finderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Das ist aber ein großer Muschelpanzer! Und der Glanz gefällt mir auch. Fängt wirklich schön das Licht ein, besonders jetzt, da wir direktes Sonnenlicht haben.\n\nWisst Ihr, womit ich mich schon eine ganze Weile nicht mehr beschäftigt habe? Wegen all der Kämpfe ums nackte Überleben? Mit der Juwelierskunst. Ich vermisse das! Wir haben früher alle möglichen Dinge gefunden, die von Euren Schiffen gefallen waren und die wir tragen konnten.\n\n<Palta zerschlägt den Muschelpanzer in viele Stücke und hält sich zwei unregelmäßig geformte Splitter an ihre Ohren.>\n\nNa, wie sehe ich aus?\n\n<Antwortet Ihr?>", sourceObjectiveStatus = "unverified-source-field" }
quests[56462] = { id = 56462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalglibber", description = "<Ihr untersucht den Kadaver des Abgrundaals, der mit einem merkwürdigen Schleim überzogen ist.\n\nDer Schleim bedeckt Eure Hände und Arme und scheint sich nur schwer wieder entfernen zu lassen.\n\nEiner Eurer Verbündeten aus der Tiefsee weiß vielleicht mehr darüber.>", sourceObjective = "Zeigt den AalglibberFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid ja ganz schön mit Schleim bedeckt. Habt Ihr was dagegen, wenn ich mir etwas davon nehme?\n\nAalglibber ist für uns unglaublich nützlich. Es gibt nicht vieles, das man benutzen kann, um Dinge unter Wasser schlüpfrig zu machen, wisst Ihr? Aalglibber ist großartig geeignet dafür.\n\nHier, ich zeige es Euch.\n\n<Palta reibt etwas Glibber auf Eure Arme und Beine.>\n\nEure Haut sieht schon viel besser aus! Schleimiger. Viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[56463] = { id = 56463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gescheckte Hydraschuppe", description = "<Die Schuppe eines kürzlich bezwungenen Hydrajungen. Sie scheint vielfarbig zu sein.\n\nOffenbar gibt es unter den Hydras dieser Region einen Kampf um die Vorherrschaft. Einer Eurer neuen Verbündeten weiß vielleicht mehr.>", sourceObjective = "Zeigt die gescheckte HydraschuppeFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Ihr würdet gern etwas mehr über die Hydras in der Gegend erfahren? Da gibt es ehrlich gesagt nicht viel zu erzählen.\n\nEs gibt drei Matriarchinnen, die sich seit Generationen um die Vorherrschaft hier in der Gegend streiten.\n\nManchmal werfen die Naga ihnen zur Belustigung Sklaven vor.\n\nSie dienen niemandem, nur sich selbst. Die Tiefen haben sich nicht gegen Euch verschworen, Neuling. Sie sind nur... feindselig gegenüber Fremdlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56464] = { id = 56464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Organ", description = "<Ihr findet ein seltsames Organ im Leichnam des Geistbeugers. Als Ihr es aufhebt, beginnt Euer Kopf zu pulsieren.\n\nDie oktopusähnlichen Kreaturen sind eines der alten Geheimnisse Azeroths. Vielleicht kann dieses Organ etwas Licht ins Dunkel bringen.\n\nJemand in Neuheim weiß vielleicht mehr.>", sourceObjective = "Zeigt das seltsame Organ Finderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Das Gehirnorgan eines Geistbeugers? Großartig, danke, das kann ich gebrauchen.\n\nSie benutzen diese Organe, um unsere Gedanken anzugreifen. Oder zumindest ist es ein Teil des Vorgangs.\n\nHier, passt auf.\n\n<Palta zeigt mit dem Organ auf Euch und pikst hinein. Ihr hört einen ohrenbetäubenden psychischen Schrei in Eurem Geist.>\n\nEs ist, als ob sie nur dafür geschaffen wären, den Alten Göttern zu dienen und die Leute in den Wahnsinn zu treiben.\n\nJedenfalls danke. Ich werde das hier behalten, bis meine Bekannte vorbeikommt, um über ihre Gartenarbeit zu reden.", sourceObjectiveStatus = "unverified-source-field" }
quests[56465] = { id = 56465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwucherter Stein", description = "<Ein Stein von einem Erdelementar, den Ihr vor Kurzem besiegt habt. Er ist bedeckt mit Tang und diversen anderen Wasserpflanzen.\n\nIhr habt noch nicht viele dieser Kreaturen in den Tiefen gesehen. Vielleicht steckt ja etwas dahinter.\n\nEiner Eurer neuen Unterwasserverbündeten weiß vielleicht mehr.>", sourceObjective = "Zeigt den überwucherten Stein Finderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "He, was ist das? Da habt Ihr einen wirklich flauschigen Stein.\n\nIst der von einem dieser Erdelementare? Oh, klasse, den kann ich gut gebrauchen. Darauf wächst alles wie verrückt, ich muss ihn nur in den Garten legen und die nächste Ernte wird großartig.\n\nIch bin nicht sicher, wo die Elementare herkamen. Wir sehen sie nicht oft, sie sind ziemlich selten.\n\nJedenfalls danke! Ich glaube, mit dem hier lege ich meinen eigenen Seetanggarten an.", sourceObjectiveStatus = "unverified-source-field" }
quests[56466] = { id = 56466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knisternde Mandibel", description = "<Die Mandibel eines Gezeitenwächters, die immer noch vor Elektrizität knistert.\n\nEiner Eurer neuen Verbündeten könnte vielleicht Verwendung dafür haben.>", sourceObjective = "Zeigt die knisternde MandibelFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "Auwei! Ihr müsst die Leute warnen, bevor Ihr ihnen etwas so Elektrisches in die Hände gebt! Ihr habt das hier von einem Gezeitenwächter?\n\nDie Gezeitenwächter bewachen das Nagareich schon so lange ich denken kann. Anscheinend waren sie immer miteinander verbandelt, denn ich kann mich nicht erinnern, einen davon jemals in der Wildnis gesehen zu haben.\n\nSie sind wunderschön, wenn sie schwimmen, geradezu hypnotisch.\n\nSei's drum, ich benutze diese Dinger, um daraus Getränke herzustellen. Man mischt etwas Tangblütenwein mit etwas gemahlener Mandibel und dann haut das richtig rein!", sourceObjectiveStatus = "unverified-source-field" }
quests[56467] = { id = 56467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzyreißzahn", description = "<Ihr nehmt dem gefallenen Frenzy einen ausgewachsenen Reißzahn ab.\n\nIhr habt von einigen Seefahrern gehört, die Waffen oder Dekorationen aus Reißzähnen herstellen, die in den Tiefen gefunden wurden. Vielleicht haben Eure neuen Verbündeten Verwendung dafür?>", sourceObjective = "Zeigt den FrenzyreißzahnFinderin Palta in Neuheim in Nazjatar.\n\nBereitgestellter Gegenstand:", completion = "<Palta stupst gegen die Spitze des Reißzahns.>\n\nEin Frenzyreißzahn, was? Diese Dinger... über die machen wir keine Scherze.\n\n<Palta sieht zum Himmel auf.>\n\nIhr habt Glück, dass sie nicht länger herkommen können.\n\nIch weiß noch, einmal waren wir unterwegs und haben nach Vorräten gesucht. Ich war die Einzige, die es schaffte, zurückzukehren. Ich höre immer noch das Schreien all derer, die verschlungen wurden. Zu Hunderten erschienen sie aus dem Nichts. Alles war nur noch eine rote Wolke.\n\nDie Tiefen der Welt sind gefährlich, mein Freund. Geht ihnen aus dem Weg, wenn Ihr könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56469] = { id = 56469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten? Ich hasse diese Typen!", description = "<Ein alter Piratenhut. Er wirkt auf dieser Insel deplatziert. Vielleicht weiß Reno Jackson, was davon zu halten ist.>", sourceObjective = "Bringt den alten Piratenhut zu Reno Jackson.\n\nBereitgestellter Gegenstand:", completion = "Ich hatte mir schon gedacht, dass es hier Piratenaktivitäten gibt! Diese ganzen merkwürdigen Dinge, die wir finden, gehören zu ihrer Beute.", sourceObjectiveStatus = "unverified-source-field" }
quests[56470] = { id = 56470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Knochen knacken!", description = "Louison hat mir Knochenknacker ausgeliehen, um ein paar Marklarven aufzuspüren, aber ich bin mit den Öfen hier beschäftigt. Könntet Ihr so lieb sein und für mich jagen gehen?\n\nKnochenknacker macht sich gerne über die kleinen Knabberer her und macht dabei eine Menge Lärm. Das wird die größeren Marklarven in die Flucht schlagen.\n\nBenutzt einfach diesen leckeren Knochen, um Knochenknacker in die Nähe der Knabberer zu locken. Oh, und vergesst bitte nicht, Fleisch von den riesigen Marklarven mitzubringen! Um das geht es nämlich.", sourceObjective = "Sammelt 12 Stücke Marklarvenfleisch von riesigen Marklarven.", progress = "Habt Ihr das Fleisch gesammelt?", completion = "Wunderbar! Daraus machen wir was Leckeres!", sourceObjectiveStatus = "unverified-source-field" }
quests[56471] = { id = 56471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unrentable Unterfangen", description = "Dieses Land ist jetzt schon eine Katastrophe monumentalen Ausmaßes, aber es könnte noch schlimmer werden!\n\nDie Venture Company ist hier und wird dieses Land für jedes bisschen Profit ausbeuten. Wir müssen ihre Projekte hier so unrentabel machen, dass sie wieder verschwindet.\n\nZerstört die drei teuren Sicherheitseinheiten, die sie bei sich haben, und sie suchen vielleicht anderswo lukrative Geschäftsmöglichkeiten.", sourceObjective = "Zerstört Verprügler Rot, Verprügler Orange und Verprügler Grau.", completion = "Das wird auf jeden Fall ihren Profit schmälern. Jetzt werden wir ja sehen, ob sie verschwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[56472] = { id = 56472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abkommen von Uldum", description = "Ihr wünscht Unterstützung bei der Verteidigung der Schmiede des Ursprungs? Da scheinen wir dasselbe Ziel zu verfolgen.\n\nDie Hallen des Ursprungs sind nur ein kleiner Teil der gesamten Schmiede. Jede Bedrohung für Uldum wäre auch eine potenzielle Bedrohung für die Schmiede, und Uldum sieht sich in letzter Zeit vielen neuen Feinden gegenüber.\n\nWir wollten uns gerade mit dem Hohen Rat treffen, als die Wüstenwanderer unerwartet aufkreuzten. Vielleicht könntet Ihr mit uns diese neuen Bedrohungen untersuchen?", sourceObjective = "Erfahrt mehr über die Bedrohungen für Uldum in Ramkahen.", progress = "Bevor wir weitermachen, sollten wir so viel wie möglich über die Bedrohungen in Erfahrung bringen, denen Uldum ausgesetzt ist.", completion = "Unser Abkommen mit den Wüstenwanderern und der Forscherliga wird unsere Verteidigung von Uldum stärken.\n\nDoch selbst mit vereinten Kräften werden wir Euch brauchen, um die Feinde abzuwehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[56473] = { id = 56473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftüberzogener Spinnenfangzahn", description = "Sogar vorsichtige Bienen sind diesen gewaltigen Spinnen zum Opfer gefallen. Die Spinnen liegen in der Nähe von Blumenbeeten auf der Lauer und überfallen die sammelnden Bienen hinterrücks. Dank Euch müssen sie sich nun über eine Spinne weniger den Kopf zerbrechen.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt den giftüberzogenen Spinnenfangzahn zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter summt Euch zu.>\n\nBzzzzzzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56474] = { id = 56474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachel der Schwarmtöterin", description = "Wespen sind natürliche Feinde der Bienen und es gibt keine tödlicheren als diese hochspezialisierten Killer. Diese Wespe wird den Stock nie wieder terrorisieren, und das ist Euch zu verdanken.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt den Stachel der Schwarmtöterin zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter summt lebhaft, als sie den Stachel sieht.>\n\nBzzzzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56475] = { id = 56475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewundenes Yetihorn", description = "Alle möglichen Kreaturen werden von dem süßen Geruch des frischen Honigs angelockt, aber nur recht wenige sind bereit, die schmerzhaften und oft tödliche Stiche der größten Bienen auszuhalten. Dieser Yeti ist dem Stock allerdings ein ständiger Dorn im Auge gewesen... bis jetzt.\n\nDie Schwarmmutter wird sich für diesen Gegenstand interessieren.", sourceObjective = "Bringt das gewundene Yetihorn zur Honigrückenschwarmmutter, um eine Belohnung zu erhalten.\n\nBereitgestellter Gegenstand:", completion = "<Die Schwarmmutter summt lebhaft, als sie das Horn sieht.>\n\nBzzzzt! Bzzzzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56489] = { id = 56489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastloser Tod", description = "Gerüchte sind im Umlauf, dass sich ausgerechnet in Stratholme neue, böse Dinge abspielen. Ihr müsst Euch für uns in die Östlichen Pestländer begeben und allen üblen Bedrohungen, die sich dort womöglich neu angesiedelt haben, ein Ende bereiten.\n\nEin Mitglied des Argentumkreuzzugs hat mit uns Verbindung aufgenommen und seine Unterstützung dabei angeboten, Euch Zugang zu Stratholme zu verschaffen und die Quelle dieses neuen Bösen aufzuspüren.", sourceObjective = "Findet Sean Wilkers vor dem Bediensteteneingang von Stratholme in den Östlichen Pestländern.", completion = "Tote Dinge sind in Stratholme wirklich keine Überraschung mehr, aber es gibt dort eine neue lauernde Gefahr, die wir noch nicht kennen.\n\nNur die Mutigsten und Willensstärksten sollten es wagen, hineinzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56490] = { id = 56490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastloser Tod", description = "Gerüchte sind im Umlauf, dass sich ausgerechnet in Stratholme neue, böse Dinge abspielen. Ihr müsst Euch für uns in die Östlichen Pestländer begeben und allen üblen Bedrohungen, die sich dort womöglich neu angesiedelt haben, ein Ende bereiten.\n\nEin Mitglied des Argentumkreuzzugs hat mit uns Verbindung aufgenommen und seine Unterstützung dabei angeboten, Euch Zugang zu Stratholme zu verschaffen und die Quelle dieses neuen Bösen aufzuspüren.", sourceObjective = "Findet Sean Wilkers vor dem Bediensteteneingang von Stratholme in den Östlichen Pestländern.", completion = "Tote Dinge sind in Stratholme wirklich keine Überraschung mehr, aber es gibt dort eine neue lauernde Gefahr, die wir noch nicht kennen.\n\nNur die Mutigsten und Willensstärksten sollten es wagen, hineinzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56491] = { id = 56491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winzige Schrecken von Stratholme", description = "Die Aktivitäten der Geißel in Stratholme haben in den letzten Tagen dramatisch zugenommen. Der Gestank von Nekromantie liegt in der Luft und überall innerhalb dieser Mauern sind Schreie und Gekreische zu vernehmen, die Euch auf Wochen hinaus kalte Schauer über den Rücken jagen werden.\n\nIch habe mich bisher noch nicht hineingewagt, aber dort drinnen regt sich auf jeden Fall neues Übel. Ich besitze die Schlüssel für diesen Eingang und kann Euch hineinbringen, damit Ihr Euch das selbst ansehen könnt.\n\nLasst es mich wissen, wenn Ihr bereit seid.", sourceObjective = "Besiegt Schwarzmähne.", completion = "Was haben sie Schwarzmähne angetan?! Wer sind diese Leute? Einem Tier nekromantische Kräfte aufzuzwingen, klingt wirklich so, als ob sie im Vergleich zu früher noch schlimmere Dinge tun. Was könnten sie nur mit all dem Zeug anfangen wollen, das sie sich nehmen? Es klingt so, als stünde ein Entscheidungskampf unmittelbar bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[56492] = { id = 56492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampfherausforderung: Stratholme", description = "Die dunkle Macht ist wieder nach Stratholme zurückgekehrt. Das ist das Problem mit Nekromantie und der Geißel, sie beleben sich einfach immer wieder und kommen zurück!\n\nIch kann uns dort wieder hineinbringen, aber ich vermute, dass all die bösen Kräfte zurückgekehrt sind. Seid Ihr sicher, dass Ihr dort wieder hineinwollt? Der Ort ist mir unheimlich. Wenn Ihr Euch wirklich wieder hineinbegeben wollt, werde ich Euch einlassen.", sourceObjective = "Besiegt Schwarzmähne.", completion = "Was haben sie Schwarzmähne angetan?! Wer sind diese Leute? Einem Tier nekromantische Kräfte aufzuzwingen, klingt wirklich so, als ob sie im Vergleich zu früher noch schlimmere Dinge tun. Was könnten sie nur mit all dem Zeug anfangen wollen, das sie sich nehmen? Es klingt so, als stünde ein Entscheidungskampf unmittelbar bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[56493] = { id = 56493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkte Vorgehensweise", description = "Maokka hat so ein sanftes Herz. Er geht so gut mit den Kleinen um, spielt immer mit ihnen und erzählt ihnen Geschichten.\n\nDiese Mitarbeiter der Venture Co. missfallen uns allerdings außerordentlich, also schlage ich eine direktere Vorgehensweise vor.\n\nVersucht, sie alle zu töten.", sourceObjective = "Beseitigt 12 Angestellte der Venture Co.", completion = "Ihr habt Ihnen einen Botschaft überbracht, die sie nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[56494] = { id = 56494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abend vor der Schlacht", description = "{name}. Die Zeit ist gekommen.\n\nWir mögen Azshara besiegt haben, aber wir müssen uns immer noch mit Sylvanas auseinandersetzen. Obwohl unsere Position nicht ideal ist, haben wir unsere verfügbaren Truppen mobilisiert und stehen bereit, um diesen Krieg zu beenden.\n\nKönig Wrynn wollte, dass ich Euch über die Lage ins Bild setze, bevor wir uns ihm anschließen. Es gab einige... interessante Entwicklungen.", sourceObjective = "Sprecht mit Mathias Shaw.", completion = "Ich danke Euch, dass Ihr umgehend gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[56495] = { id = 56495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie ziehen gegen uns zu Felde", description = "Die Dunkle Fürstin hat um Eure Anwesenheit in Orgrimmar gebeten, {name}.\n\nDie Ratten trauen sich endlich aus der Deckung. Das macht es leichter für uns, sie zu zerquetschen.\n\nBeeilt Euch. Auf diesen Moment haben wir lange genug gewartet.", sourceObjective = "Trefft Euch mit Sylvanas in Orgrimmar.", completion = "Diesen Verrätern muss der Garaus gemacht werden. Keine Nachsicht mehr. Keine Schwäche mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[56496] = { id = 56496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abend vor der Schlacht", description = "{name}, wir müssen über die Horde sprechen... und den Kriegshäuptling.\n\nDer Krieg ist uns teuer zu stehen gekommen und die Schlacht gegen Azshara hat die wenigen Ressourcen, die uns noch zur Verfügung standen, aufgezehrt. Die Horde ist wieder einmal gespalten und der Allianz geht es kaum besser als uns. \n\nSylvanas ist jetzt in der Position, alle zu vernichten, die sie als Feinde betrachtet. Das schließt uns mit ein.\n\nIch hatte gehofft, dass meine alte Freundin zur Vernunft kommen würde, aber jetzt...\n\nHochfürst Saurfang schart alle um sich, die von uns noch übrig sind... und einige unwahrscheinliche Verbündete.", sourceObjective = "Sprecht mit Lor'themar.", completion = "Wir haben viel zu tun, {name}. Die Banshee handelt schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[56499] = { id = 56499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtfelder stürmen", description = "Wir können es uns nicht leisten, an irgendeiner Front nachzulassen, also treibt den Krieg weiter voran.", sourceObjective = "Gewinnt eine PvP-Inselexpedition, ein normales Schlachtfeld und ein episches Schlachtfeld.", completion = "Wenn wir den Druck aufrechterhalten, wird die Horde niemals Erfolg haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56500] = { id = 56500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtfelder stürmen", description = "Wir können es uns nicht leisten, an irgendeiner Front nachzulassen, also treibt den Krieg weiter voran.", sourceObjective = "Gewinnt eine PvP-Inselexpedition, ein normales Schlachtfeld und ein episches Schlachtfeld.", completion = "Wenn wir den Druck aufrechterhalten, wird die Allianz niemals Erfolg haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56501] = { id = 56501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luft rauslassen", description = "<Diese Kiste voller Raketen könnte man dazu verwenden, die Ballons der Venture Co. abzuschießen. Das würde die Venture Co. wirklich dazu motivieren, woanders hinzugehen.>", sourceObjective = "Beseitigt 5 Transporter der Venture Co.", completion = "Ihr seid großzügig. Ihr habt weit mehr als das getan, worum ich Euch gebeten hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[56504] = { id = 56504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furorions Tagebuch", sourceObjective = "Bringt Furorions unvollständiges Tagebuch zu MUTTER.", completion = "Informationen aus Tagebuchseiten gespeichert. Arbeite Verstärkungsbaupläne für Herzkammer aus.\n\nAlle Daten wurden aufgezeichnet und katalogisiert. Physische Transkription werden nicht länger benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56508] = { id = 56508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts verschwenden", description = "<Es gibt verschiedene Ersatzteile in diesem Gebiet, die für den Rostbolzen nützlich sein könnten. Ihr solltet sie einsammeln, bevor die Venture Co. ihrer habhaft werden kann.>", sourceObjective = "Sammelt 20 nützliche Teile.", progress = "Schnappt Euch alles, was Ihr könnt!", completion = "Mit diesen Teilen kann man prima jemanden aufwerten!", sourceObjectiveStatus = "unverified-source-field" }
quests[56515] = { id = 56515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallplatte: Gnomeregan für immer", description = "<Diese Schallplatte aus gepresstem Vinyl ist überraschenderweise immer noch gut erhalten. Laut Aufschrift handelt es sich um eine Aufnahme des Liedes \"Gnomeregan für immer\".\n\nIhr könnt diese Schallplatte sicher in das Grammophon im Rostbolzen einlegen.>", sourceObjective = "Legt die Schallplatte in das Rostbolzengrammophon ein.\n\nBereitgestellter Gegenstand:", completion = "<Die Schallplatte gleitet sauber auf den Plattenteller des Grammophons. Die Titelanzeige aktualisiert sich automatisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56516] = { id = 56516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallplatte: Mimirons Gedankenblitz", description = "<Diese Schallplatte aus gepresstem Vinyl ist überraschenderweise immer noch gut erhalten. Laut Aufschrift handelt es sich um eine Aufnahme des Liedes \"Mimirons Gedankenblitz\".\n\nIhr könnt diese Schallplatte sicher in das Grammophon im Rostbolzen einlegen.>", sourceObjective = "Legt die Schallplatte in das Rostbolzengrammophon ein.\n\nBereitgestellter Gegenstand:", completion = "<Die Schallplatte gleitet sauber auf den Plattenteller des Grammophons. Die Titelanzeige aktualisiert sich automatisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56517] = { id = 56517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallplatte: Schlacht von Gnomeregan", description = "<Diese Schallplatte aus gepresstem Vinyl ist überraschenderweise immer noch gut erhalten. Laut Aufschrift handelt es sich um eine Aufnahme des Liedes \"Schlacht von Gnomeregan\".\n\nIhr könnt diese Schallplatte sicher in das Grammophon im Rostbolzen einlegen.>", sourceObjective = "Legt die Schallplatte in das Rostbolzengrammophon ein.\n\nBereitgestellter Gegenstand:", completion = "<Die Schallplatte gleitet sauber auf den Plattenteller des Grammophons. Die Titelanzeige aktualisiert sich automatisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56518] = { id = 56518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallplatte: Tiefen von Ulduar", description = "<Diese Schallplatte aus gepresstem Vinyl ist überraschenderweise immer noch gut erhalten. Laut Aufschrift handelt es sich um eine Aufnahme des Liedes \"Tiefen von Ulduar\".\n\nIhr könnt diese Schallplatte sicher in das Grammophon im Rostbolzen einlegen.>", sourceObjective = "Legt die Schallplatte in das Rostbolzengrammophon ein.\n\nBereitgestellter Gegenstand:", completion = "<Die Schallplatte gleitet sauber auf den Plattenteller des Grammophons. Die Titelanzeige aktualisiert sich automatisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56519] = { id = 56519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallplatte: Triumph von Gnomeregan", description = "<Diese Schallplatte aus gepresstem Vinyl ist überraschenderweise immer noch gut erhalten. Laut Aufschrift handelt es sich um eine Aufnahme des Liedes \"Triumph von Gnomeregan\".\n\nIhr könnt diese Schallplatte sicher in das Grammophon im Rostbolzen einlegen.>", sourceObjective = "Legt die Schallplatte in das Rostbolzengrammophon ein.\n\nBereitgestellter Gegenstand:", completion = "<Die Schallplatte gleitet sauber auf den Plattenteller des Grammophons. Die Titelanzeige aktualisiert sich automatisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56523] = { id = 56523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Hühner sind nicht zum Essen da!", description = "Wenn Ihr mal Zeit mit diesem überheblichen Schwachkopf Oberfunks verbracht habt, wisst Ihr, warum ich hier bin.\n\nUm seine Angeberei zum Schweigen zu bringen und endlich zu beweisen, dass meine Erfindungen besser sind!\n\nIch habe zahllose mechanische Hühner auf dieser Insel ausgesetzt, damit sie die Technologie hier analysieren, sie übernehmen und ihre eigenen Schaltkreise entwickeln. Eins davon wird mein ultimatives Kampfhuhn werden!\n\nAber diese idiotischen Troggs glauben, meine Hühner wären essbar und hauen sie ständig platt.\n\nBeschützt sie, damit mein techno-evolutionäres Experiment seinen Lauf nehmen kann.", sourceObjective = "Sammelt 20 mechanische Innereien und repariert den OOX-Bomber/MG.", progress = "Man stelle sich das nur vor... Wie kann jemand so dumm sein, ein mechanisches Huhn zu essen...", completion = "Eine Erfindung der Superlative, {name}!\n\nUnd jetzt lehnen wir uns zurück und überlassen die Roboter ihrer Evolution durch natürliche Selektion... ohne jegliche negativen Nebenwirkungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56532] = { id = 56532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norbit der Zerstörer", description = "Diese Motospinnen vermehren sich komplett unbehelligt. Wenn wir das nicht unterbinden, werden sie den Rostbolzen bald überrennen.\n\nIch habe Norbit hier modifiziert, sodass er jetzt über genügend Feuerkraft verfügt, um es mit den Motospinnen aufzunehmen!\n\nWürdet Ihr bitte Norbit steuern und die verstärkten Funkennetzeier zerstören?", sourceObjective = "Zerstört die 5 verstärkten Funkennetzeier.", progress = "Norbit braucht einen erfahrenen Piloten!", completion = "Mission erfüllt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56533] = { id = 56533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltadergerüchte", description = "Sammelt Informationen für den SI:7, indem Ihr den Standort der wogenden Weltader herausfindet.", sourceObjective = "Sammelt 3 Weltaderspionageberichte.", progress = "Habt Ihr genug Informationen gesammelt?", completion = "Genau nach dieser Information sollte ich für Mathias Shaw meine Ohren offenhalten. Ich werde es ihm sofort berichten. Ich bin mir sicher, dass er schon eine weitere Mission für Euch hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[56534] = { id = 56534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltadergerüchte", description = "Sammelt weitere Informationen, um Eure Anhänger bei der Suche nach der wogenden Weltader zu unterstützen.", sourceObjective = "Sammelt 3 Weltaderspionageberichte.", progress = "Habt Ihr genug Informationen gesammelt?", completion = "Nathanos Pestrufer hat nach genau dieser Art von Informationen gesucht. Ich schicke sofort einen Läufer zum Flaggschiff. Ich bin mir sicher, dass er eine weitere Mission für Euch bereithält, wenn Ihr dort ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56536] = { id = 56536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach ist es nie", description = "Meinen letzten Informationen nach ist das Mogu'shangewölbe noch immer verlassen.\n\nEs sollte uns nicht sonderlich schwerfallen, die Maschine zu erreichen, da wir schon die dortigen Moguwächter bezwungen haben.\n\nNun, worauf wartet Ihr noch? Schalten wir die Maschine an!", sourceObjective = "Trefft Magni Bronzebart außerhalb des Mogu'shangewölbes am Kun-Lai-Gipfel.", progress = "Wirklich einfach ist es nie, oder?", completion = "Die Bernbarriere sieht praktisch undurchdringbar aus.\n\nIch denke, wir befinden uns in einer Sackgasse...", sourceObjectiveStatus = "unverified-source-field" }
quests[56537] = { id = 56537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das geheimnisvolle Siegel", description = "<Der tote Mogu hält ein Siegel fest in der Hand. Es trägt das Symbol seines geheimnisvollen Klans.\n\nWenn Ihr seinen Klan ausfindig macht, könnt Ihr womöglich mehr über die Invasion der Mantis im Mogu'shangewölbe in Erfahrung bringen und einen Weg finden, um sie zurückzuschlagen.\n\nLehrensucher Cho ist in Pandaria für sein großes Wissen bekannt. Vielleicht kann er den Ursprung des Mogusiegels ergründen.>", sourceObjective = "Bringt das geheimnisvolle Mogusiegel zu Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", completion = "Also wurde das Mogu'shangewölbe von den Mantis eingenommen? Wahrlich eine merkwürdige Wendung, auch wenn sie mich nicht wirklich überrascht.\n\nEs jedoch mithilfe der Mogu zurückerobern zu wollen, das hätte ich nicht erwartet. Ich hatte keine Ahnung, dass sie zur Kooperation bereit wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[56538] = { id = 56538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klans der Mogu", description = "Ihr sagt, ein Mogu hätte Euch um Hilfe gebeten? Das ist sehr ungewöhnlich.\n\nIch helfe Euch gern, den Ursprung des Siegels zu ergründen. Um ehrlich zu sein, finde ich die Aussicht auf einen freundlich gesinnten Moguklan äußerst verlockend. Denkt nur an die Möglichkeiten!\n\nDann mal an die Arbeit. Wir müssen die Bücher über die verschiedenen Moguklans im Tal durchgehen, um die Suche einzugrenzen.", sourceObjective = "Helft Lehrensucher Cho im Heim des Wissens dabei, den Ursprung des geheimnisvollen Mogusiegels zu ergründen.", progress = "Warum sprecht Ihr mich an? Das von Euch begehrte Wissen findet Ihr in den Folianten.", completion = "Wenn die Mogu wieder Ra-den folgen, könnte dies ein Ende ihrer kriegerischen Tage bedeuten.\n\nDas ist richtig aufregend!", sourceObjectiveStatus = "unverified-source-field" }
quests[56539] = { id = 56539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach den Rajani", description = "Da wir nun wissen, wen wir suchen, bleibt nur die Frage, wo wir sie finden.\n\nBei den ständigen Streitigkeiten zwischen den Mogu werden die verschiedenen Klans einander im Blick behalten. Und ihre Informationen könnten uns sicher zu den Rajani führen.\n\nFindet die Champions der Mogu. Sie werden die Berichte über die Aufenthaltsorte ihrer Gegner höchstwahrscheinlich bei sich tragen.", sourceObjective = "Besorgt den Späherbericht der Mogu im Tal der Ewigen Blüten.", progress = "Habt Ihr einen Späherbericht gefunden?", completion = "Ausgezeichnet. Das könnte uns nicht nur zu den Rajani führen, sondern auch der Verteidigung des Goldenen Lotus zugutekommen.\n\nWahrlich wertvolles Wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[56540] = { id = 56540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis der Hartnäckigkeit", description = "Wenn der hohe Hüter sich so sicher ist, dass wir gegen unsere Feinde keine Chance haben, müssen wir ihn wohl mit einer Machtdemonstration überzeugen.\n\nIch bin nicht sicher, wie Ihr es vollbringen wollt, aber wenn Ihr uns den Beweis für einen Sieg gegen diejenigen, die das Tal bedrohen, überbringen könntet, würde das sicher reichen, um ihn zum Handeln zu bewegen.", sourceObjective = "Beschafft eine Trophäe des Eroberers vom Kommandanten eines Angriffs im Tal der Ewigen Blüten.", progress = "Was ist es diesmal?", completion = "Ihr habt also einen der Möchtegerneroberer des Tals bezwungen? Eine beachtliche Leistung, aber Azeroths Feinde sind zahllos.\n\nDie Brennende Legion, die Alten Götter, die Leere... früher oder später wird diese Welt erliegen.\n\n...Allerdings habe ich mich auch schon zuvor geirrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56541] = { id = 56541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschine von Nalak'sha", description = "Euer Volk hat mich schon früher eines Besseren belehrt, also verdient Ihr die Chance, dies noch einmal zu versuchen.\n\nDas Titanengebilde, in dem sich die Maschine von Nalak'sha befindet, erstreckt sich über ganz Pandaria. Es gibt mehr Wege dorthin als nur durch das Mogu'shangewölbe.\n\nViele Wege, doch am schnellsten kommt ihr durch den Mogu'shanpalast dorthin. Die Kammern unter dem Palast sind mit dem Gewölbe verbunden. \n\nVersucht Euer Schicksal dort, Champion.", sourceObjective = "Folgt dem Geheimgang im Mogu'shanpalast und reaktiviert die Maschine von Nalak'sha.", completion = "Ihr habt heute Großes für die Rajani getan, Champion.\n\nIch hoffe, Ihr habt durch die Maschine von Nalak'sha die Energie, die Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56542] = { id = 56542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederhergestellte Hoffnung", description = "Eure Entschlossenheit schenkt mir Hoffnung für diese Welt.\n\nKehren wir in Eure \"Herzkammer\" zurück. Ich denke, dass ich Euch als Hüter der Schmiede des Ursprungs dabei behilflich sein kann, sie wiederherzustellen.\n\nSprecht mit mir, wenn Ihr bereit seid, dann bringe ich uns dorthin.", sourceObjective = "Sprecht mit Ra-den, um zur Herzkammer zurückzukehren.", completion = "Wir haben die Schmiede des Ursprungs nicht nur wieder mit Energie versorgt, sondern sogar den Titanenhüter zurückgeholt, der sie gebaut hat!\n\nAber damit hören die guten Neuigkeiten noch nicht auf, ob Ihr es glaubt oder nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[56550] = { id = 56550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenbeseitigung", description = "Immer mehr unserer Freunde fallen, während diese grässlichen Insekten aus ihren Nestern schwärmen und unsere Lager angreifen.\n\nEs ist eine schreckliche Bitte, aber wir müssen die Leichen schnellstmöglich entsorgen.\n\nWir können nicht zulassen, dass unsere Toten als Dünger zur Aufzucht ihrer widerlichen Eier benutzt werden.", sourceObjective = "Verbrennt 8 eiertragende Leichen.", progress = "Wir müssen diese Aufgabe schnell und unverzüglich erledigen.", completion = "Ich hoffe, das wird helfen, ihre Vermehrung in Schach zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56552] = { id = 56552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfe unter der Hand", description = "Hat Euch Gazlowe auch zum Schutz angeheuert? Anscheinend stimmt es, dass er nur die besten Leute beschäftigt, was? Ha!\n\nDie Bezahlung ist super, aber die Regeln sind Mist: keine Kämpfe in der Stadt, keine Ausnahmen. Bah!\n\n<Usha nimmt einen großen Schluck von ihrem Getränk.>\n\nDieser kleine, zarte Prinz wird uns niemals seine Technik zur Verfügung stellen, wenn er nicht denkt, dass wir friedliche, liebe Engel sind... Ha!\n\nGazlowe hat allerdings nichts von Kämpfen außerhalb der Stadt gesagt.\n\nIch habe draußen schon eine Mannschaft zusammen, die bereit ist, es mit Grumbols Säufern aufzunehmen, wenn sie ihre bärtigen Visagen blicken lassen.\n\nWollt Ihr mitmachen?", sourceObjective = "Rauft Euch mit den Leuten von Grumbol Grimmhammer in Mechagon.", completion = "Ha ha ha! Seht Euch nur Grumbols dämliches Gesicht an!\n\nEr kann es kaum glauben! Ha ha ha! Armselig!", sourceObjectiveStatus = "unverified-source-field" }
quests[56557] = { id = 56557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haue hintenrum", description = "Es gibt nur zwei Dinge, die ich noch mehr liebe als Kämpfen. Nummer eins ist ordentlich Sprüche klopfen!\n\n<Usha brüllt Grumbol Grimmhammer eine Beleidigung entgegen.>\n\nDieser Zwerg mit dem Bart eines Wildschweins ist mir seit Alterac ein Dorn im Auge... Das kratzt ihn aber anscheinend gar nicht.\n\nWir haben eine Wette laufen, wer der beste Kämpfer auf der Insel ist.\n\nWollt Ihr mir beim Gewinn dieser Wette helfen?", sourceObjective = "Tötet 5 Spielercharaktere der Allianz in Mechagon.", completion = "Ha! Wie es aussieht, schulde ich Euch ein weiteres Getränk.", sourceObjectiveStatus = "unverified-source-field" }
quests[56558] = { id = 56558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfe unter der Hand", description = "*Rüüülps* Aaaaalso gut, hört zu. Wir befinden uns hier in einer Zwickmühle.\n\nAbgesehen davon, dass das Bier in diesem Loch hier wie Öl schmeckt, hat sich die Schweinetreiberin namens Usha ein paar blöde Sprüche über unsere Streitkräfte geklopft.\n\nBlöd für SIE, weil *rüüüülps*, weil Ihr jetzt jedes Hordenschwein aufmischen werdet, das Euch da draußen über den Weg läuft.\n\nWir haben eigentlich die Anweisung, hier nicht zu kämpfen, also ist das kein offizieller Auftrag oder so...", sourceObjective = "Rauft Euch mit den Leuten von Usha Hohlauge in Mechagon.", completion = "Könnte kaum stolzer auf Euch sein, mein Junge! Hier habt Ihr was für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56559] = { id = 56559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haue hintenrum", sourceObjective = "Tötet 5 Spielercharaktere der Horde in Mechagon.", completion = "Ich wusste, dass Ihr mich nicht im Stich lasst!", sourceObjectiveStatus = "unverified-source-field" }
quests[56560] = { id = 56560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine merkwürdige Entdeckung", description = "<Dieser Kristall strahlt ein hypnotisierendes Licht aus, von dem Ihr Euren Blick kaum losreißen könnt.\n\nVielleicht können Euch die Entfesselten mehr darüber erzählen.>", sourceObjective = "Bringt den faszinierenden Kristall zu Narv in Neuheim.\n\nBereitgestellter Gegenstand:", completion = "Ich habe diese Kristalle schon an verschiedenen Orten gesehen. Meistens befindet sich in ihrer Nähe merkwürdiger Schleim. Das muss irgendwie zusammenhängen, aber ich weiß noch nicht wie.\n\nZumindest ist der einzige Nutzen dieser Kristalle, den ich bis jetzt ausgemacht habe, dass mir kleine Kreaturen eine Zeit lang folgen.\n\nTut mir leid, dass Euch das nicht viel weiterhilft, aber Ihr könnt Euren Kristall zurückhaben. Lasst es mich wissen, falls Ihr noch etwas anderes herausfindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[56561] = { id = 56561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine merkwürdige Entdeckung", description = "<Dieser Kristall strahlt ein hypnotisierendes Licht aus, von dem Ihr Euren Blick kaum losreißen könnt.\n\nVielleicht können Euch die Ankoaner mehr darüber erzählen.>", sourceObjective = "Bringt den faszinierenden Kristall zu Ausbilder Okanu in Mezzameer.\n\nBereitgestellter Gegenstand:", completion = "Ich habe diese Kristalle schon an verschiedenen Orten gesehen. Meistens befindet sich in ihrer Nähe merkwürdiger Schleim. Da muss es irgendeinen Zusammenhang geben, aber ich habe ihn noch nicht entdeckt.\n\nZumindest ist der einzige Nutzen dieser Kristalle, den ich bis jetzt ausgemacht habe, dass man damit kleine Kreaturen für eine Zeit hypnotisieren kann.\n\nTut mir leid, dass Euch das nicht viel weiterhilft, aber Ihr könnt Euren Kristall zurückhaben. Lasst es mich wissen, falls Ihr noch etwas anderes herausfindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[56562] = { id = 56562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschrumpelproblem", description = "<Nachdem Ihr unzählige Tiere gehäutet habe, kommt Ihr unweigerlich zu dem Schluss, dass beim Trocknen und Gerben der Tierhaut sehr viel brauchbares Leder verloren geht. Die Ankoaner scheinen die Verarbeitung des Materials perfektioniert zu haben. Vielleicht kann Euch Ausbilder Ulooaka etwas darüber sagen.>", sourceObjective = "Fragt Ausbilder Ulooaka nach der verschrumpelten Tierhaut.\n\nBereitgestellter Gegenstand:", completion = "Verzeiht mir. Die Arbeit mit dem Material ist unser tägliches Brot, deshalb habe ich ganz vergessen, Euch zu erklären, wie man das vermeidet. Die Tiere sind normalerweise immer unter Wasser, und die Haut trocknet an der Luft ungleichmäßig. Wenn Ihr die Tiere häutet, müsst Ihr die Bälge direkt aufrollen. So werden sie feucht gehalten und bleiben in gutem Zustand.", sourceObjectiveStatus = "unverified-source-field" }
quests[56563] = { id = 56563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschrumpelproblem", description = "<Nachdem Ihr unzählige Tiere gehäutet habe, kommt Ihr unweigerlich zu dem Schluss, dass beim Trocknen und Gerben der Tierhaut sehr viel brauchbares Leder verloren geht. Die Entfesselten scheinen ein tiefes Verständnis für die Verarbeitung des Materials entwickelt zu haben. Vielleicht kann Euch Rolm etwas darüber sagen.>", sourceObjective = "Fragt Rolm nach der verschrumpelten Tierhaut.\n\nBereitgestellter Gegenstand:", completion = "Ah, stimmt. Entschuldigt bitte. Die Arbeit mit dem Material ist unser tägliches Brot, deshalb habe ich ganz vergessen, Euch zu erklären, wie man das vermeidet. Also, die Tiere sind normalerweise immer unter Wasser und die Haut trocknet an der Luft ungleichmäßig. Wenn Ihr die Tiere häutet, müsst Ihr die Bälge direkt aufrollen. So werden sie feucht gehalten und bleiben in gutem Zustand.", sourceObjectiveStatus = "unverified-source-field" }
quests[56565] = { id = 56565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am seidenen Faden", description = "<Als Ihr das Tier häutet, bemerkt Ihr, dass dabei zahlreiche Schuppen abbrechen und Löcher in die Haut reißen, wodurch sie unbrauchbar wird. Die Ankoaner scheinen die Verarbeitung des Materials perfektioniert zu haben. Vielleicht kann Euch Ausbilder Ulooaka etwas darüber sagen.>", sourceObjective = "Fragt Ausbilder Ulooaka nach den zerfallenden Klippenschuppen.\n\nBereitgestellter Gegenstand:", completion = "Das habe ich schon oft gesehen. Die Schuppen dieser Tiere sind nicht nur ein Teil ihrer Haut, sondern sie sind auch mit den Muskeln und Sehnen verbunden. So können die Tiere besser durch die Tiefen streifen. Wenn Ihr die Haut entfernen wollt, dann macht das in zwei Schritten. Als Erstes schneidet Ihr die sehnigen Fasern ab und dann häutet Ihr das Tier. So wird ein viel größerer Teil der Tierhaut nutzbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[56566] = { id = 56566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am seidenen Faden", description = "<Als Ihr das Tier häutet, bemerkt Ihr, dass dabei zahlreiche Schuppen abbrechen und Löcher in die Haut reißen, wodurch sie unbrauchbar wird. Die Entfesselten scheinen die Verarbeitung des Materials perfektioniert zu haben. Vielleicht kann Euch Rolm etwas darüber sagen.>", sourceObjective = "Fragt Rolm nach den zerfallenden Klippenschuppen.\n\nBereitgestellter Gegenstand:", completion = "Das habe ich schon einmal gesehen. Also, die Schuppen dieser Tiere sind nicht nur ein Teil ihrer Haut, sondern sie sind durch starke Muskeln und Sehnen verbunden. So kann das Tier besser durch die Tiefen streifen. Wenn Ihr die Haut entfernen wollt, dann macht das in zwei Schritten. Als Erstes scheidet Ihr die Schuppen frei und dann häutet Ihr das Tier. So wird ein viel größerer Teil der Tierhaut nutzbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[56570] = { id = 56570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen der Ströme", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56572] = { id = 56572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielzeuge wie wir", description = "Ich muss die Wunder dieses Ortes mit ganz Azeroth teilen, und zwar so, dass Alt und Jung gleichermaßen unterhalten werden. Ich werde die hiesige Technologie verwenden, um eine neue Reihe von Spielzeugen zu erschaffen, die man so noch nicht gesehen hat!\n\nMein quasifacettierter Scanner kann bei der Herstellung von perfekten Nachbildungen der Dinge auf dieser Insel helfen.\n\nIch brauche nur einen hilfsbereiten Champion wie Euch, der ein paar Dinge in dieser Gegend für mich scannt.", sourceObjective = "Wendet den quasifacettierten Scanner auf Kreaturen in Mechagon an.", completion = "Die erste Charge Spielzeuge ist fertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[56573] = { id = 56573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zertifiziert aus zweiter Hand", description = "Ich möchte zuerst noch betonen, dass Ihr IMMER unser Lieblingsversuchsobjekt sein werdet.\n\nUnsere Experimente erfordern aber weit mehr Opfer, als ein einzelnes Versuchsobjekt bringen kann. Manchmal brauchen einige dieser Versuchsobjekte auch neue Gliedmaßen.\n\nMein teurer Bruder und ich arbeiten an einem ambitionierten Konzept zur Verlängerung der durchschnittlichen Lebenszeit von mechanischen Gliedmaßen. Aber wir haben keine Komponenten mehr, mit denen wir experimentieren können.\n\nBergt einige Gliedmaßen aus dem Haufen vor der Stadt, damit wir unsere Experimente fortsetzen können.", sourceObjective = "Sammelt 15 wiederverwertete Mechagnomgliedmaßen.", progress = "Kümmert Euch nicht um kaputte oder fehlende Teile. Nora wird uns helfen, die Dinge zu reparieren, die Ihr findet.", completion = "Wundervoll! Das sollte reichen für...\n\n<Pristy zählt die Gliedmaßen und kritzelt etwas in ihr Notizbuch.>\n\n...mindestens drei Stunden. Mann, diese Gliedmaßen sind immer ruckzuck weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[56574] = { id = 56574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelungen im Bern", description = "<Ein zäher, dunkler Schlamm tropft von diesem großen Bernbrocken. Ihn abzuwischen hat keinen Zweck, da offenbar der Bern selbst den Schlamm erzeugt.\n\nAls Ihr ihn in den Händen haltet, dringt ein unverständliches Flüstern in Eure Gedanken.\n\nDie Shado-Pan werden das untersuchen wollen.>", sourceObjective = "Bringt den schlammbedeckten Bern zu den Shado-Pan am Schlangenrücken.", completion = "Was habt Ihr da, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[56575] = { id = 56575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Kor'vess", description = "Ihr habt dies bei einem Schergen des Schwarms gefunden? Es trieft vor Verderbnis... und Macht. Wenn der restliche Bern der Mantis ähnlich verderbt ist, sehen wir uns einer ernsthaften Bedrohung gegenüber.\n\nWeit im Westen, in der Schreckensöde, liegt Kor'vess. Das ist ein großer Kyparibaum, der den Schwarm mit dem Großteil seines Berns versorgt. Dort können wir bestimmen, wie viel von ihrem Vorrat mit der Energie der Alten Götter verseucht ist.\n\nWir treffen uns näher an diesem Baum.", sourceObjective = "Untersucht Kor'vess.", completion = "Die Mantis scheinen den gesamten Baum zu verderben. Es ist schlimmer, als ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[56576] = { id = 56576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung der Aqir", description = "Hier fliegen zu viele von diesen Viechern herum, als dass wir gefahrlos verschwinden könnten.\n\nSobald wir einen Flugzeugmotor anwerfen, werden die uns in Schwärmen angreifen!\n\nDie Käfer landen letztendlich so oder so wieder in der Erde... Da können wir den Vorgang auch etwas beschleunigen. Verstehen wir uns?", sourceObjective = "Tötet 10 Pfähler der Aqir.", completion = "Damit sollten wir für eine Weile freie Bahn haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[56577] = { id = 56577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schwarm lahmlegen", description = "Die Mantis hier arbeiten eifrig, um Bern vom Baum zu ernten.\n\nVielleicht hält es sie ein wenig auf, wenn Ihr ein paar Pfotenvoll von ihnen tötet.", sourceObjective = "Tötet 12 Mantis der Kor'thik in Kor'vess.", completion = "Dies wird zwar keine dauerhafte Lösung sein, sollte uns aber etwas Zeit verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56578] = { id = 56578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fäulnis von der Wurzel her", description = "Unterhalb von Kypari Kor liegt eine große Kammer, in der die Mantis den Baum versorgen. Dort muss die Quelle der Verderbnis liegen.\n\nWir müssen dort hineingelangen und das aufhalten. N'Zoth darf den Schwarm nicht ermächtigen.", sourceObjective = "Setzt der Quelle der Verderbnis in der Morgenkammer ein Ende.", completion = "Gesichtslose? Die Kyparibäume sind den Mantis heilig... aber ihre Ergebenheit den Alten Göttern gegenüber wiegt wohl schwerer.", sourceObjectiveStatus = "unverified-source-field" }
quests[56580] = { id = 56580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse im Bern", description = "Die Morgenkammer beherbergt einen kleinen Teil der Zara'thik, also der Mantis, die direkt der neuen Kaiserin unterstehen. Einige von ihnen haben vielleicht Bernstücke wie das erhalten, was Ihr gefunden habt.\n\nDie Shado-Pan wären sehr an weiteren Stücken interessiert, wenn wir sie beschaffen können.", sourceObjective = "Sammelt 8 Stücke verderbten Bern.", progress = "Wir haben immer befürchtet, dass dieser Tag kommt...", completion = "Ah, noch mehr von diesem verderbten Bern. Ich muss ihn zurück zur Garnison bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56616] = { id = 56616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Gesichter, neue Probleme", description = "Einer von N'Zoths Dienern scheint uns bemerkt zu haben.\n\nSollen wir ihm einen Besuch abstatten?", sourceObjective = "Tötet Beobachter Vl'thax.", completion = "Noch ein Handlanger N'Zoths. Die Mantis scheinen seine Gunst erworben zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56617] = { id = 56617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vereinter Schwarm", description = "Die Mantis scheinen den verderbten Bern schon eine ganze Zeit lang produziert zu haben, bevor wir... eingegriffen haben. Da scheint es wahrscheinlich, dass sie irgendwo einen Vorrat davon haben.\n\nDie Späher der Shado-Pan melden in letzter Zeit mehr Krieger des Schwarms in Klaxxi'vess. Ich wette, die bewachen den verderbten Bern.\n\nTrefft mich dort. Falls sich eine Gelegenheit bietet, den Bern zu zerstören, müssen wir sie ergreifen.", sourceObjective = "Infiltriert Klaxxi'vess.", completion = "Sollte der gesamte Schwarm vom verderbten Bern gestärkt werden, so hätte N'Zoth eine unaufhaltsame Armee unter seinem Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[56621] = { id = 56621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrhaft ultimative Kraft", description = "Wenn ich sage, dass Strom Leben ist, meine ich das nicht bildlich, mein teures Versuchsobjekt.\n\nWenn er richtig genutzt wird, kann Strom sogar Leben entstehen lassen... oder zumindest ein ziemlich genaues Faksimile für unsere Zwecke.\n\nWeit unten in den schlammigen Tiefen des Auslasses gibt es einen enormen Vorrat an ausgemusterter Technologie. Wie schon zuvor wird Mechagons Schrott zu unserem Schatz.\n\nEndlich habe ich auch mein Gerät soweit perfektioniert, dass es den Schlick zum Leben erweckt, der Euch dann diese Technologie herauf an die Oberfläche holt.\n\nIhr müsst den Schlick dann nur noch aufplatzen lassen und Euch die Technologie schnappen!", sourceObjective = "Sammelt 15 ausgemusterte Technologie von technikanimiertem Schlick.", progress = "Bitte dokumentiert genau etwaige negative Nebeneffekte, die Ihr während der Verwendung des Induktor-7143 bemerkt.", completion = "Großartige Bergung!\n\nUnd Ihr sagt, dass der Induktor-7143 KEIN extrem brennendes Gefühl in Euren Eingeweiden erzeugt hat?\n\n<Flip notiert sich etwas und lächelt.>\n\nDas ist wirklich wundersam!", sourceObjectiveStatus = "unverified-source-field" }
quests[56622] = { id = 56622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft in Ashran", description = "Die Allianz weigert sich, in Ashran nachzugeben. Zeigt ihr, dass die Horde nicht einfach tatenlos zusieht, während sie die Macht des alten Ogerreichs für ihre Zwecke an sich reißt.", sourceObjective = "Besiegt die Allianz an allen Ereignisstandorten in Ashran und tötet Großmarschall Tremblade.", sourceObjectiveStatus = "unverified-source-field" }
quests[56623] = { id = 56623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft in Ashran", description = "Wie wir schon befürchtet haben, versucht die Horde mit Raubzügen ihre Stellung hier auf der Insel zu festigen. Zieht hinaus und zeigt ihnen, dass die Allianz sich derartige Überfälle nicht gefallen lässt.", sourceObjective = "Besiegt die Horde an allen Ereignisstandorten in Ashran und tötet den Obersten Kriegsfürsten Volrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[56640] = { id = 56640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mal davongekommen", description = "Wir beide haben den Angriff überlebt und konnten der Gefangennahme durch den Feind entgehen.\n\nAber es hatten nicht alle so viel Glück.\n\nViele unserer Verbündeten stehen jetzt unter der Kontrolle der Naga. Wir müssen sie befreien, bevor sie getötet werden oder ein noch schlimmeres Schicksal erleiden.", sourceObjective = "Rettet 7 gefangene Soldaten in Azsharas Speeren.", completion = "Unsere Armee wurde zerschlagen, aber wir werden sie neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56641] = { id = 56641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung der Macht", description = "Die Naga machen Gebrauch von irgendeiner latenten Kraft und speisen die Energie in eine Art Gerät ein.\n\nIch weiß nicht, was sie mit dieser Kraft vorhaben, aber es ist sicherlich in unserem Interesse, diese Objekte zu zerstören, bevor sie gegen uns verwendet werden können.", sourceObjective = "Zerstört 5 Leylinienakkumulatoren in Azsharas Speeren.", completion = "Manchmal macht es richtig Spaß, das Spielzeug anderer Leute zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[56642] = { id = 56642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gezeiten", description = "Eine Gezeitenherrin führt ein schändliches Ritual oberhalb eines Beckens aus.\n\nSchaut nicht in das Becken, wenn wir uns dem Geschehen nähern, sonst müsst Ihr den Anblick Eurer ertrunkenen Verbündeten ertragen.\n\nWir müssen dieses Ritual unterbinden. Die Gezeitenherrin ist der Schlüssel dazu.", sourceObjective = "Tötet Gezeitenherrin Ethendriss.", completion = "Das Ritual hörte sofort auf, nachdem wir die Gezeitenherrin getötet hatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[56643] = { id = 56643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer hinein", description = "König Graumähne und Lady Prachtmeer müssten sich mittlerweile in der Höhle befinden, in der wir uns treffen wollten.\n\nWir sollten sie nicht warten lassen.", sourceObjective = "Trefft Euch mit Jaina und Genn in der Höhle in Azsharas Speeren.", completion = "Ich habe diesen Ort jetzt schon satt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56644] = { id = 56644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Rücken zur Wand", description = "Wir müssen uns beeilen, wenn wir unsere Leute in Sicherheit bringen wollen.\n\nDiese Höhle ist kaum zu verteidigen und ein Großteil unserer Armee ist in einer noch bedenklicheren Position.\n\nLasst uns tiefer vordringen und die Höhle weiter erforschen.", sourceObjective = "Dringt mit Jaina und Genn weiter in das Innere von Nazjatar vor.", completion = "Wir haben Euch beobachtet. Eure Leute scheinen zu wissen, was sie tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[56645] = { id = 56645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Schwarms", description = "Wir müssen wissen, womit wir es zu tun haben. Bevor wir zum Schlangenrücken zurückkehren, sollten wir die Gelegenheit nutzen, den Schwarm auszuspähen.\n\nIch fliege uns über das Herz der Angst. Wir sollten die Streitkräfte der Kaiserin Shek'zara von oben auskundschaften können. Dann können wir bestimmen, inwieweit N'Zoth ihr Heer mit seinen Schergen verstärkt hat.", sourceObjective = "Fliegt mit Taoshi mit dem Drachen der Shado-Pan.", completion = "Das war knapp. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56647] = { id = 56647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Mantis", description = "Die Mantis verderben ihre Kyparibäume, um ihren Bern mit N'Zoths Macht zu erfüllen. Der Schwarm allein ist schon gefährlich genug. N'Zoth könnte ihn in etwas noch Schrecklicheres verwandeln.\n\nDie Shado-Pan müssen davon erfahren. Ich würde Euch empfehlen, auch Eure Verbündeten zu informieren.", sourceObjective = "Kehrt zu Sturmsprecher Qian im Stillen Sanktum zurück.", completion = "Dass die Mantis sogar ihre Kyparibäume der Verderbnis überlassen würden, sagt viel darüber aus, wie treu sie N'Zoth sind.\n\nDanke, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56648] = { id = 56648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Nazjatar", description = "Unsere Mission in Nazjatar wird durch die Übergriffe der Horde gestört.\n\nBegebt Euch nach Nazjatar und schaltet so viele Mitglieder der Horde aus, wie Ihr nur könnt.", sourceObjective = "Tötet Mitglieder der Horde in Nazjatar.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56649] = { id = 56649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Mechagon", description = "Unsere Mission in Mechagon wird durch die Übergriffe der Horde gestört. \n\nGeht nach Mechagon und schaltet so viele Mitglieder der Horde aus, wie Ihr nur könnt!", sourceObjective = "Tötet Mitglieder der Horde in Mechagon.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56650] = { id = 56650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Mechagon", description = "Unsere Ziele in Mechagon werden durch das Auftauchen von Allianzabschaum blockiert.\n\nTötet so viele von ihnen, wie Ihr in der Region finden könnt, und meldet Euch wieder bei mir.", sourceObjective = "Tötet Mitglieder der Allianz in Mechagon.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56714] = { id = 56714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maßvoller Bierlementar", description = "<Als das Gebräu in seinen natürlichen, inaktiven Zustand zurückkehrt, erscheint ein seltsames Fass.\n\nVielleicht weiß Braumeister Tao mehr über diesen merkwürdigen Vorfall.>", sourceObjective = "Sprecht mit Braumeister Tao auf dem Braufestplatz.", completion = "Alles trägt einen Geist in sich. Von den Wolken im Himmel bis zum kleinen Regenwurm in der Erde. Das Leben ist auf der ganzen Welt miteinander verwoben.\n\nMit dem Brauen ist es nicht anders. Wir brauen mit so viel Liebe und Hingabe... da bedarf es nur eines kleinen Funkens, um Leben direkt vor unseren Augen entstehen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56715] = { id = 56715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Ho-zen", description = "<Die Ho-zen wurden erfolgreich vertrieben und das Braufest ist wieder einmal gerettet.\n\nEs stellt sich aber durchaus die Frage, wie die Ho-zen nach Durotar gelangt sind. Vielleicht hat ja jemand auf dem Braufestplatz mehr Erfahrung mit ihnen.>", sourceObjective = "Sprecht mit Zenda auf dem Braufestplatz.", completion = "<Zenda spuckt auf das Totem der Ho-zen.>\n\nLasst Euch von ihrem Ausseh'n nich' täusch'n. Diese Ho-zen sin' unbarmherzig. Einige von denen ham mein' Bruder aus seiner eigenen Gaststätte in Zuldazar vertrieb'n un' sie übernomm'.\n\nIch hab diese Geflügelten geseh'n un' die sin' nirgendwo willkomm'.", sourceObjectiveStatus = "unverified-source-field" }
quests[56716] = { id = 56716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräuzahnrad", description = "<Die Dunkeleisenzwerge von Düsterbräu sind geflohen und haben ein kleines Teil von einer ihrer Maulwurfmaschinen zurückgelassen.\n\nIhr wisst, dass sie das Braufest schon einmal angegriffen haben. Vielleicht würde einer der Goblins gerne von Eurem Sieg hören.>", sourceObjective = "Sprecht mit Blix Fixtand auf dem Braufestplatz.", completion = "Düsterbräu gibt also immer noch nicht auf?\n\nJedenfalls danke, dass Ihr Euch erneut um seine Schergen gekümmert habt. Dank Euch bin ich noch im Geschäft! Nehmt diese Marken als Belohnung... Aber kommt auf jeden Fall wieder zurück und gebt sie später aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[56719] = { id = 56719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht meins", description = "Ihr kommt gerade rechtzeitig, {name}. Sylvanas' Loyalisten haben einen Abschnitt des Pfads durch die Schlucht nach Orgrimmar einstürzen lassen.\n\nWir sind von unserer Vorhut abgeschnitten und ich fürchte, sie wird vernichtet, wenn wir ihr nicht schnell Verstärkung zukommen lassen können. Wir haben nur wenige Truppen. Wir können es uns nicht leisten, dass sie lange festsitzen.\n\nTüftlermeister Oberfunks und Gazlowe glauben, dass sie eine Lösung haben. Beeilt Euch und unterstützt sie auf jede erdenkliche Weise.", sourceObjective = "Beseitigt Felsen, Minen und andere Hindernisse aus dem Pass zwischen Klingenhügel und Orgrimmar.", progress = "Dem Licht sei Dank, dass Ihr den Pass öffnen konntet.", completion = "Es mag uns gelungen sein, uns wieder der Vorhut anzuschließen, aber Sylvanas' Streitkräfte haben unseren Frontkämpfern zugesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56739] = { id = 56739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Anbetung", description = "Ich war einst wie sie, gefangen in einem Kreislauf, ewig in der Erwartung, dass Azshara kommen und mich retten würde. Unsere Geister sind an diesen Ort gebunden.\n\nIn den anderen Teilen dieser Ruinen halten sich Naga auf. Sie haben diese magischen Kugeln... Ich glaube, sie benutzen uns, um ihre arkanen Experimente anzutreiben. Sie ziehen Macht aus unseren Geistern und unserer Anbetung Azsharas. Das schwächt uns und hält uns davon ab, uns zu befreien.\n\nZerstört diese Kugeln. Wenn die Verbindung unterbrochen wird, erhalten wir unsere Kraft zurück, sodass wir weiterziehen können.", sourceObjective = "Zerstört 3 Arkanenergiewandler.", completion = "Ohne den Entzug der Energie sollten sich die anderen Geister aus dem Kreislauf befreien können. Und dann können auch sie weiterziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56740] = { id = 56740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung muss sein", description = "Ihr stimmt mir doch sicher zu, dass Pascal-K1N6 die genialste Erfindung ist, die Ihr je gesehen habt!\n\nWenn Ihr noch nicht überzeugt seid, dann versucht doch mal, ihn an seine Grenzen zu bringen. Nur zu!\n\nBringt ihm mehr Rohstoffe und Baupläne und er wird Euch alles bauen, was Ihr braucht!", completion = "Jetzt schau sich mal einer an, wie viele Ersatzteile Ihr in diesen Beuteln habt! Ihr seht allmählich aus wie ein echter Schrottplatztüftler.\n\nAber ich gebe Euch einen Tipp. Nur Amateure ziehen mit so einem ungeordneten Haufen durch die Gegend.\n\nEchte Experten verwenden eine effiziente Ordnung, damit man mehr mitschleppen kann.\n\nIch werde Euch zeigen, wie das geht." }
quests[56741] = { id = 56741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Speer des Schicksals", description = "Die Wurfspeere zählen zu den mächtigsten magischen Schöpfungen von Suramar, vor der Zerschlagung. Mit ihnen können wir die Zauberschutze der Wächterin und des Gezeitensteins ausschalten.\n\nWir müssen schnell zurück nach Mezzameer. Lady Prachtmeer muss von unserem Erfolg erfahren.\n\nDas wird den Verlauf unserer gesamten Kampagne hier in Nazjatar verändern, {name}.", sourceObjective = "Kehrt zu Jaina Prachtmeer in Mezzameer zurück.", completion = "Das ist ein erstaunlicher Fund, {name}. Damit können wir die Wächterin des Gezeitensteins angreifen und ihn sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[56746] = { id = 56746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direktverbindung", description = "Ihr stimmt mir doch sicher zu, dass Pascal-K1N6 die genialste Erfindung ist, die Ihr je gesehen habt!\n\nWenn Ihr noch nicht überzeugt seid, dann versucht doch mal, ihn an seine Grenzen zu bringen. Nur zu!\n\nBringt ihm mehr Rohstoffe und Baupläne und er wird Euch alles bauen, was Ihr braucht!", completion = "Madame Goya lässt ausrichten, dass sie Eure fortwährende Unterstützung ihrer Operationen zu würdigen weiß.\n\nSie hat mir aufgetragen, Euch die Pläne für unser verschlüsseltes Kommunikationsnetzwerk anzuvertrauen, damit Ihr immer in Kontakt bleiben könnt.\n\nGebt sie nie aus den Händen, {name}.\n\nWir werden Euch im Auge behalten." }
quests[56747] = { id = 56747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Akundas Biss", sourceObjective = "Bringt 20 Sturmsilbererz zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[56748] = { id = 56748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestmampfkampf", description = "Mok-rah, {class}! Ich hoffe, Ihr seid mit leerem Magen gekommen!\n\nAuf Draenor haben wir während unserer Feste oft Esswettbewerbe abgehalten. Als man uns mit dem Braufest beauftragte, war uns gleich klar, dass wir das hier auch anbieten müssen!\n\nSetzt Euch und zeigt uns, wie viel Ihr essen könnt. Und wenn Ihr vorher erst mal mehr darüber wissen wollt, dann fragt einfach!", sourceObjective = "Nehmt am Braufestmampfkampf teil.", progress = "Esst ein Würstchen, trinkt etwas Gebräu und esst dann noch mehr!", completion = "Gut gegessen! Für jeden Sieg erhaltet Ihr eine Marke als Belohnung. Wenn Ihr fünf davon habt, dann kommt zu mir zurück, damit ich Euch eine wunderschöne Trophäe übergeben kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[56749] = { id = 56749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Akundas Biss", sourceObjective = "Bringt 20 Sturmsilbererz zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
