quests[56756] = { id = 56756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Schätzchen, die Actionfigur", description = "Heda, {name}.\n\n<Grizzek beugt sich zu Euch und flüstert.>\n\nIch plane eine Überraschung für Saffy, und ich hoffe, Ihr könnt mir dabei helfen.\n\nIch hab mitgehört, wie sie Jepetto Spaßbrumm darum bat, eine Actionfigur zu bauen, die wie sie aussieht.\n\nAber der alte Trottel hat nein gesagt! Ist das zu glauben? Mein Schätzchen!\n\nAber ich brauche ihn nicht. Ich hab ein paar seiner Spielzeuge untersucht und herausgefunden, wie sie funktionieren.\n\nIch hab schon einen Bauplan fertig. Wir können selbst eine Actionfigur von Saffy bauen und sie damit überraschen!", sourceObjective = "Stellt die Actionfigur von Sapphronetta Chaise auf Pascal-K1N6 her.", progress = "In Euren Augen kann ich das Funkeln eines Entdeckers sehen!", completion = "<Sapphronettas Augen leuchten auf, als Ihr die nach ihrem Ebenbild gefertigte Actionfigur an sie übergebt.>", sourceObjectiveStatus = "unverified-source-field" }
