quests[56764] = { id = 56764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestmampfkampf", description = "Willkommen, {class}! Ich hoffe, Ihr seid mit leerem Magen gekommen!\n\nEs gibt doch nichts Besseres als Würstchen und Gebräu, oder? Nichts passt besser zum Braufest. Der Braufestmampfkampf ist unsere neue Art, die Dinge zu feiern, die dieses Fest so großartig machen.\n\nSetzt Euch und zeigt uns, wie viel Ihr essen könnt. Und wenn Ihr vorher erst mal mehr darüber wissen wollt, dann fragt einfach!", sourceObjective = "Nehmt am Braufestmampfkampf teil.", progress = "Esst ein Würstchen, trinkt etwas Gebräu und esst dann noch mehr!", completion = "Gut gegessen! Für jeden Sieg erhaltet Ihr eine Marke als Belohnung. Wenn Ihr fünf davon habt, dann kommt zu mir zurück, damit ich Euch eine wunderschöne Trophäe übergeben kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[56765] = { id = 56765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Spurschnapper", sourceObjective = "Bringt 20 Sturmsilbererz zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[56767] = { id = 56767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen der unendlichen Tiefe", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56768] = { id = 56768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen des Tiefensogs", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56769] = { id = 56769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen des weiten Horizonts", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56770] = { id = 56770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen der Ströme", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56771] = { id = 56771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitverlorene Krieger", description = "Dem Späherbericht nach, den Ihr gefunden habt, verschanzen sich die Rajani im Stillen Sanktum, das Nebelhauch überblickt.\n\nEs heißt dort, sie seien zurückgezogen und gefährlich, also sollten wir vorsichtig sein, wenn wir uns ihnen nähern.\n\nWir sehen uns dort.", sourceObjective = "Sprecht mit den Rajani im Stillen Sanktum.", progress = "Was gibt's, Fremdling?", completion = "Es hat keinen Zweck. Der hohe Hüter ist von unserem Schicksal überzeugt.\n\nWorte allein werden ihn nicht davon abbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56772] = { id = 56772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen der unendlichen Tiefe", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56773] = { id = 56773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen des weiten Horizonts", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56774] = { id = 56774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Großes Fläschchen des Tiefensogs", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Fläschchen wirklich dringend gebraucht." }
quests[56775] = { id = 56775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwärmen", description = "Macht Euch bereit, {name}. Wir nähern uns der Insel, auf der die letzte Expedition verschwunden ist.\n\nÜbt ein wenig an den Zielattrappen. Wir müssen für alles bereit sein, was uns auf der Insel erwarten könnte.", sourceObjective = "Wärmt Euch ein wenig an der Kampfattrappe auf.", progress = "Keine unnötige Scheu. Geht zu den Zielattrappen, wählt sie aus und führt Euren Hauptangriff aus.", completion = "Gut, Ihr habt offenbar Euer Training auf unserer Reise nicht vernachlässigt, {class}.\n\nDer plötzliche Wetterumschwung bereitet mir ein wenig Sorgen. Bestreitet einen Übungskampf mit dem Gefreiten Cole, während ich mit der Schiffsmannschaft spreche.\n\nColes Bewertung wird entscheiden, wie Ihr in unserem Expeditionsteam eingesetzt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[56777] = { id = 56777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk des Klans", description = "Sprecher Utia hat mich angewiesen, Euch nach Mezzameer zurückzuschicken, sobald Ihr die Möglichkeit dazu habt, {name}.\n\nUnser Klan hat ein Geschenk als Wertschätzung Eures Mutes und Eurer Tapferkeit vorbereitet, die Ihr in der Schlacht gegen die Naga gezeigt habt.\n\nIch bin mir sicher, dass Ihr die geschenkten Vorräte als eine nützliche Ergänzung Eures Arsenals brauchen könnt, wenn Ihr Euren Kampf gegen Azshara fortsetzt.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Ihr habt unserem Klan Ehre gemacht, {name}. Bitte nehmt diese zusätzlichen Vorräte mit unserem Dank an.", sourceObjectiveStatus = "unverified-source-field" }
quests[56778] = { id = 56778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Glitzern in der Dunkelheit", description = "In Nazjatar gibt es viele versteckte Schätze.\n\nIch habe vor Kurzem ein Objekt entdeckt, dessen Schein aus einer Höhle nicht weit von hier kommt. Es scheint eine Art Schließkassette zu sein.\n\nIch schlage vor, dass wir zurückgehen und uns dort noch einmal umsehen. In der Kassette befinden sich vielleicht wertvolle Gegenstände, die uns im Kampf gegen die Naga helfen könnten.", sourceObjective = "Plündert die glitzernde Schließkassette.", sourceObjectiveStatus = "unverified-source-field" }
quests[56779] = { id = 56779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohn der Tapferkeit", description = "Geschichten über Eure Taten auf dem Schlachtfeld haben Eurer Allianz Ehre gemacht, {class}.\n\nSprecher Utia hat Eure Anwesenheit in Mezzameer angefordert, um Euch eine Belohnung von unserem Klan zu überreichen.\n\nIhr solltet baldmöglichst nach Mezzameer zurückkehren.\n\nEs ist eine Ehre, an Eurer Seite zu kämpfen.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Bitte nehmt diese Vorräte als Geschenk an. Mögen sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56780] = { id = 56780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgen, aber gefährlich", description = "Die Naga haben viele nützliche Schätze in ganz Nazjatar versteckt.\n\nIch habe Gerüchte gehört, dass es nicht weit von hier einen Schatz geben soll. Es wird zwar nicht ungefährlich, aber ich glaube, es lohnt sich, mal nachzusehen.\n\nVielleicht gibt es darin unsagbare Kostbarkeiten, die uns in unserem Kampf gegen die Naga helfen können.", sourceObjective = "Plündert die mystische Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[56781] = { id = 56781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz in der Tiefe", description = "In der Festung der Naga in Nazjatar gibt es viele Schätze zu finden.\n\nVor einiger Zeit habe ich eine mysteriös anmutende Kiste bemerkt. Das Gebiet ist schwer von Nagatruppen bewacht, weswegen ich glaube, dass etwas Wertvolles darin sein muss.\n\nWir sollten zurückgehen und die Kiste untersuchen. Was auch immer darin ist, ist in unseren Händen besser aufgehoben als in denen unserer Feinde.", sourceObjective = "Plündert die mysteriöse Kiste.", sourceObjectiveStatus = "unverified-source-field" }
quests[56782] = { id = 56782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk des Sprechers", description = "Sprecher Utia erwartet Euch in Mezzameer, {name}.\n\nIch glaube, der Sprecher hat eine Sammlung von Gegenständen für Euch vorbereitet, die Euch auf Eurer Reise helfen werden.\n\nIhr solltet nach Mezzameer zurückkehren, sobald Ihr könnt, und das Geschenk von Sprecher Utia entgegennehmen.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Bitte nehmt dieses Geschenk von unserem Klan an. Möge es Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56783] = { id = 56783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die glitzernde Schließkassette", description = "In diesen uralten Ruinen gibt es unzählige Schätze zu finden.\n\nVor einiger Zeit habe ich eine merkwürdige Kiste in einer Höhle in der Nähe entdeckt.\n\nVielleicht befinden sich darin wertvolle Gegenstände, die uns in unserem Kampf gegen Königin Azshara helfen könnten.\n\nWir sollten zurückgehen und die Kiste untersuchen.", sourceObjective = "Plündert die glitzernde Schließkassette.", sourceObjectiveStatus = "unverified-source-field" }
quests[56784] = { id = 56784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nützliche Vorräte", description = "Sprecher Utia erwartet Eure Ankunft in Mezzameer.\n\nDer Sprecher hat Euch ein Paket nützlicher Vorräte zusammengestellt, die Euch auf Eurer Reise helfen werden.\n\nBitte nehmt dieses Geschenk mit dem Dank unseres Klans an.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Bitte nehmt diese Vorräte als Geschenk an. Mögt Ihr für Euren Kampf gegen die Naga immer gut ausgerüstet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56785] = { id = 56785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die mystische Truhe", description = "Beim Erforschen von Nazjatar haben wir viele seltene Schätze entdeckt. Ich glaube, ich habe noch eine Truhe mit wertvollen Artefakten gefunden, die darauf wartet, geborgen zu werden.\n\nVor einiger Zeit habe ich ein merkwürdig leuchtendes Objekt in der Ferne gesehen. Ich glaube, dass es eine Schatztruhe gewesen sein könnte.\n\nWir sollten das Objekt untersuchen. Wenn es eine Schatztruhe ist, könnte ihr Inhalt sich für unsere Anstrengungen gegen die Naga als nützlich erweisen!", sourceObjective = "Plündert die mystische Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[56786] = { id = 56786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaschatz", description = "Die Naga haben die Beute ihrer Kriege in ganz Nazjatar versteckt.\n\nAls wir vor einiger Zeit unterwegs waren, habe ich eine mysteriöse Kiste erspäht. Sie befindet sich allerdings tief im Nagagebiet, also glaube ich, dass ihr Inhalt wahrscheinlich sehr wertvoll ist.\n\nWir sollten uns den Inhalt der Kiste sichern. Was auch immer darin ist, ist in unseren Händen besser aufgehoben als in denen unserer Feinde.", sourceObjective = "Plündert die mysteriöse Kiste.", sourceObjectiveStatus = "unverified-source-field" }
quests[56787] = { id = 56787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Vorräte", description = "Sprecher Utia hat mich gebeten, Euch nach Mezzameer zu schicken, {name}.\n\nDer Sprecher hat zusätzliche Vorräte für Euch vorbereitet, die Euch auf Eurer Reise helfen werden.\n\nIhr solltet bald nach Mezzameer zurückkehren und das Geschenk von Sprecher Utia zusammen mit dem Dank unseres Klans entgegennehmen.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Mögen diese zusätzlichen Vorräte Euch bei Eurer Reise helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[56788] = { id = 56788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergefundene Schätze", description = "Überall in Nazjatar haben die Naga ihre geplünderte Kriegsbeute versteckt. Wir sollten uns alles zurückholen, was wir auf unserem Weg finden, während wir die Tyrannei der Naga ein für alle Mal beenden.\n\nIn einer Höhle in der Nähe habe ich eine merkwürdige Kiste entdeckt. Nach ihrer Machart stammt sie von den Naga.\n\nWir sollten uns den Inhalt der Kiste holen. Darin befinden sich vielleicht wertvolle Gegenstände, die uns bei unserem Kampf gegen die Naga helfen können.", sourceObjective = "Plündert die glitzernde Schließkassette.", sourceObjectiveStatus = "unverified-source-field" }
quests[56789] = { id = 56789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenkte Vorräte", description = "Sprecher Utia hat mich gebeten, Euch so bald wie möglich nach Mezzameer zu schicken.\n\nDer Sprecher hat Vorräte für Euch zusammengestellt, die Euch bei Eurem Kampf gegen die Naga helfen werden.\n\nIhr solltet bald nach Mezzameer zurückkehren und das Geschenk von Sprecher Utia zusammen mit dem Dank unseres Klans entgegennehmen.", sourceObjective = "Trefft Euch mit Sprecher Utia.", completion = "Bitte nehmt diese Vorräte als Geschenk an. Mögen sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[56790] = { id = 56790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz zu finden", description = "Die Naga haben in ganz Nazjatar Schätze versteckt.\n\nVor einiger Zeit habe ich eine kunstvoll gefertigte Schatztruhe entdeckt. Das Gebiet ist zwar schwer bewacht, aber solche geringfügigen Hindernisse haben uns ja noch nie aufgehalten.\n\nWir sollten dorthin zurückgehen und uns den Inhalt der Truhe holen.", sourceObjective = "Plündert die mystische Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[56791] = { id = 56791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Schatz", description = "Bei unseren Streifzügen durch Nazjatar haben wir einige Schätze entdeckt. Ich glaube, ich habe eine weitere Kiste ausgemacht, die wir uns holen sollten.\n\nVor Kurzem habe ich eine merkwürdig anmutende Kiste bemerkt. Sie befindet sich ein einem sehr gefährlichen Gebiet, also ist ihr Inhalt sicherlich wertvoll.\n\nWir sollten uns auf den Weg begeben und die Truhe bergen. Was auch immer darin ist, ist in unseren Händen besser aufgehoben als in denen unserer Feinde.", sourceObjective = "Plündert die mysteriöse Kiste.", sourceObjectiveStatus = "unverified-source-field" }
quests[56793] = { id = 56793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Mech-Dowels \"Big Mech\"", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Nahrung wirklich dringend gebraucht." }
