quests[56802] = { id = 56802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Mech-Dowels \"Big Mech\"", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Nahrung wirklich dringend gebraucht." }
quests[56803] = { id = 56803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein Freund", description = "Also, Schlammfuß, ich muss sichergehen, dass Ihr nicht schon von der kleinsten Strömung umgehauen werdet.\n\nIch habe Atolia gebeten, nachzusehen, ob sie nicht ein paar Dinge zusammensuchen kann, die Euch hier ein bisschen weniger nutzlos machen.\n\nNach dem, was ich in dem letzten Kampf gesehen habe, sollten wir besser früher als später zurückkehren.", sourceObjective = "Besucht Atolia Seeperl in Neuheim.", completion = "Eine Anmerkung am Rande: Dass Ihr diesen Griesgram weiterhin ertragt ist löblich.\n\nMal sehen, was ich noch finden kann, falls Ihr später immer noch zusammenarbeitet.\n\nIch zähle auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[56804] = { id = 56804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer solche Freunde hat...", description = "Manchmal unternehme ich zum Spaß Ausflüge zur Terrasse der Zanj'ir, wo die harten Jungs der Naga sich aufhalten.\n\nDort sammle ich Dinge ein, die mir nützlich erscheinen, und bewahre sie an einer sicheren Stelle auf, wo ich sie später abholen kann.\n\nIch war schon lange nicht mehr dort.\n\nIch könnte etwas haben, dass Ihr vielleicht brauchen könnt.", sourceObjective = "Seht nach, was sich in Vims Truhe befindet.", completion = "<Die Bewegung der Tentakel erzeugt eine hübsche Brise auf dieser schwülen Terrasse.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56805] = { id = 56805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund, ein guter Freund...", description = "Hmm. Ich gebe hier gar nichts zu, aber es könnte sein, dass es eine minimal kleine Chance gibt, dass ich mich vielleicht doch ein kleines Bisschen getäuscht habe... über Eure ganze... Sache.\n\nFür den unwahrscheinlichen Fall, dass wir uns weiterhin tolerieren, hat Atolia eine weitere Lieferung für Euch erwähnt.\n\nWir sollten in Neuheim vorbeischauen.", sourceObjective = "Besucht Atolia Seeperl in Neuheim.", completion = "Wir Entfesselten helfen uns gegenseitig.\n\nSo sind wir erfolgreich gewachsen. So sind wir stark geblieben... vielleicht nicht sehr charmant, aber stark.\n\nVim ist ein guter Freund, besonders wenn man gelernt hat, seine aufgesetzte harte Schale zu ignorieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[56806] = { id = 56806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde auf ewig", description = "Ihr habt vielleicht bemerkt, dass ich mit den Meeresriesen sehr gut auskomme.\n\nEigentlich wollen sie meistens nur in Ruhe gelassen werden. Sie wollen lachen und erzählen ständig Geschichten, die absolut keinen Sinn ergeben.\n\nEin einfaches Leben.\n\nEin Interesse haben wir neben dem Töten von Naga jedoch gemeinsam, und zwar das Verkosten interessanter Gebräue.\n\nMaedin hat kürzlich ein wunderbares neues Fass mitgebracht und ich habe es versteckt. Wenn die Zeit gekommen ist, es zu öffnen, geht die erste Runde davon auf mich!\n\nKommt, seht es Euch an!", sourceObjective = "Besucht Vims Runde.", completion = "<In das Holz ist eine Nachricht geschnitzt.\n\n\"Die besten Gebräue sind die, die man mit Freunden teilt.\">", sourceObjectiveStatus = "unverified-source-field" }
quests[56807] = { id = 56807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Freunde helfen, Leichen zu verstecken", description = "Leichen... Schätze... \n\nIch habe all das gesehen, aber lange bevor ich jemanden gefunden habe, den ich als wahren Freund bezeichnen kann.\n\nIch bin froh, dass ich Euch zu dieser Liste hinzugefügt habe.\n\nAlso zurück zu diesen Freunden... Es gibt noch einen Platz, den ich Euch zeigen möchte.", sourceObjective = "Findet Gorms Laterne.", completion = "<Auf der Plakette steht:\n\nDie, die Ihr unterwegs trefft, machen die Reise erst wertvoll.\n\nGorm war ein guter Kämpfer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56808] = { id = 56808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir werden Freunde", description = "Das wird sicher lustig, Euch kennenzulernen. Ihr seid gar nicht mal so schlecht!\n\nWir haben ein kleines Geschenk für Euch, um Euch in der Nachbarschaft willkommen zu heißen.\n\nIch hoffe, Atolia konnte etwas Schönes für Euch zusammenstellen. Sie hatte nämlich nicht viel Zeit.", sourceObjective = "Besucht Atolia Seeperl in Neuheim für Eure Belohnung.", completion = "Sieht aus, als ob Ihr gut hierher passt. Macht so weiter, junger Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[56809] = { id = 56809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superfreunde", description = "Ihr seid <ein/eine> super duper wuper <Freund/Freundin>!\n\nEs gibt einen Platz, an dem ich meine kleineren Freunde besuche. Ich sammle schöne Dinge, die ich finde, dort in einer Tasche.\n\nWollt Ihr sie sehen?\n\nWas frage ich da? Natürlich wollt Ihr! Gehen wir!", sourceObjective = "Seht nach, was sich in Poens Tasche befindet.", completion = "<In der Tasche befindet sich eine Notiz mit der Aufschrift \"Poen, vergiss nicht: Jeder Tag bringt neue Hoffnung. - Poen\">", sourceObjectiveStatus = "unverified-source-field" }
quests[56810] = { id = 56810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein echter Freund", description = "Jeder Tag mit Euch bringt ein neues Abenteuer, <mein Freund/meine Freundin>. \n\nEuer Schiffbruch tut mir leid, aber ich bin so froh, dass wir uns kennengelernt haben!\n\nIch habe Gerüchte gehört, dass Atolia neue Waren gefunden hat!\n\nWir sollten vorbeischauen und nachsehen, was sie Neues anbieten kann!", sourceObjective = "Besucht Atolia Seeperl in Neuheim für Eure Belohnung.", completion = "So glücklich habe ich Poen schon lange nicht mehr gesehen.\n\nIhr das hier und mehr verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[56811] = { id = 56811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In mir habt Ihr einen Freund gefunden", description = "Es gibt einige Orte, die ich gerne mit meinen Freunden besuche.\n\nIch habe dieses wirklich erstaunliche... Etwas gefunden, aber ich weiß nicht, was es ist.\n\nKönntet Ihr es für mit mir untersuchen?", sourceObjective = "Untersucht Poens Geheimversteck.", completion = "<Offensichtlich spielt Poen gern den einen oder anderen Streich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56812] = { id = 56812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft ist Magie", description = "Jeden Tag, an dem ich mit Euch unterwegs bin, hab ich das Gefühl, dass ich eine bessere Kelfinne werde.\n\nIhr habt keine Ahnung, was das für mich bedeutet.\n\nIch wollte immer mehr machen, mehr sein... mehr helfen.\n\nIch werde jetzt immer mehr zu einem richtig vollwertigen Mitglied der Entfesselten.\n\nUnd all das dank Euch.", sourceObjective = "Sucht Poens Wunder auf.", completion = "<Die Bewegung ist recht entspannend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56813] = { id = 56813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter Freund", description = "Oh, {name}, das habe ich beinahe vergessen!\n\nAtolia und ich haben einige Gegenstände zusammengestellt, die Euch bei Eurer Aufgabe hier in Nazjatar helfen könnten.\n\nWir sollten mal bei ihr vorbeischauen, sobald wir Zeit haben!", sourceObjective = "Besucht Atolia Seeperl in Neuheim für Eure Belohnung.", completion = "Willkommen in unserer wunderschönen, aber auch schrecklichen kleinen Nachbarschaft.\n\nWenn Ihr überlebt, kann ich vielleicht noch mehr Gegenstände für Euch auftreiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[56814] = { id = 56814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls Ihr je einen Freund braucht", description = "Ihr seid nicht schlecht für <einen/eine:r>... Was seid Ihr? <Ein/Eine:r> {race}?\n\nIch finde es immer wieder gut, wenn mich etwas daran erinnert, über die äußere Erscheinung hinwegzusehen. Ha!\n\nAber wenn wir schon von Dingen sprechen, die gut sichtbar versteckt sind. Ich habe einige Dinge in einer Nagakiste versteckt. Sie befindet sich in der Nähe eines ihrer Lager in Azsharas Speere, sodass sie niemals vermuten würden, dass sie mir gehört!\n\nLasst uns nachsehen, ob die Kiste immer noch dort ist.", sourceObjective = "Findet Neris List.", completion = "<Ihr nehmt einen leichten Geruch nach Salz und Leder wahr.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56815] = { id = 56815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit etwas Hilfe von guten Freunden", description = "Es ist schon sehr lange her, dass wir jemandem vertrauen konnten, der nicht unserer kleinen Gruppe von Überlebenden angehört.\n\nIch habe ganz vergessen, wie gut sich das anfühlt.\n\nDanke, dass Ihr mich daran erinnert habt.\n\nAtolia hat den Rest Eures Geschenks mittlerweile bestimmt zusammengestellt. Wir sollten ihr einen Besuch abstatten!", sourceObjective = "Besucht Atolia Seeperl in Neuheim für Eure Belohnung.", completion = "Wisst Ihr, wenn alle an Land so großartig sind wie Ihr, dann werde ich mal vorbeischauen, sobald wir alle wieder frei sind.\n\nEs ist nicht viel, aber ich hoffe, Ihr findet hier etwas Nützliches!", sourceObjectiveStatus = "unverified-source-field" }
quests[56816] = { id = 56816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund einer Kelfinne", description = "In unserem Kampf gibt es keine bessere Waffe als das Wissen.\n\nIhr seid der lebende Beweis dafür!\n\nIch habe das hier gefunden. Damit kann ich besser sehen, als es mit meinen eigenen Augen je möglich war.\n\nJetzt, wo das Wasser weg ist, kann ich sogar in die Ferne blicken! Ich habe es manchmal benutzt, um zu sehen, was in Nazjatar vor sich geht.\n\nIch zeige es Euch!", sourceObjective = "Untersucht Neris Fund.", completion = "<In das Rohr sind die folgenden Worte schwach eingeritzt: \"Niemand ist eine Insel, aber wenn Ihr eine sucht, nehmt das hier mit!\">", sourceObjectiveStatus = "unverified-source-field" }
quests[56817] = { id = 56817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke für Eure Freundschaft", description = "Seit der Wasserwall aufgetaucht ist, hat sich hier so viel verändert. \n\nIch habe eine kleine Stelle gefunden, wo Ihr fühlen könnt, wie die Meeresgischt Euer Gesicht liebkost. \n\nManchmal reite ich einfach dort hinüber und ruhe mich aus.\n\nIch werde Euch die Stelle zeigen, wenn Ihr wollt.", sourceObjective = "Genießt Neris Plätzchen.", completion = "<Wenn sie gestört werden, geben diese Korallen einen Duft von Blumen und Wäldern ab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[56818] = { id = 56818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Waffe - Nagahaut", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Verzauberungen wirklich dringend gebraucht." }
quests[56819] = { id = 56819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Waffe - Ozeanische Wiederherstellung", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Verzauberungen wirklich dringend gebraucht." }
