quests[56827] = { id = 56827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Waffe - Nagahaut", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, mein Freund. Wir haben diese Verzauberungen wirklich dringend gebraucht." }
quests[56829] = { id = 56829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gründler", description = "Oh, das ist schlecht. Sogar richtig schlecht.\n\nJedes Mal, wenn es einer der Jungs nach hier unten schafft, kommt er nicht wieder hoch. Alles, was hier runterkommt... bleibt auch auf irgendeine Weise hier.\n\nIch möchte Euch etwas vorschlagen. Ihr seid ja <ein Schlundgänger/eine Schlundgängerin>. Findet Ihr doch Knüppelfratze und den Kämmerer, während ich diese Kutsche hier in Schuss bringe, damit wir alle von hier verschwinden können, BEVOR sich irgendwas über uns hermachen will.", sourceObjective = "Findet Knüppelfratze und den Obersten Kämmerer.", completion = "Ah, gut. Niemand ist gefressen worden.\n\nDie Kutsche ist bereit, wenn Ihr es seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[56830] = { id = 56830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerufen aus den Tiefen" }
quests[56833] = { id = 56833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Horde", description = "Saurfang hat sein wahres Gesicht gezeigt und nimmt die Hilfe der Allianz in Anspruch. \n\nTrefft Euch mit jenen, die weiter loyal zur Horde stehen. Sie haben sich auf die Schlacht gegen unsere Feinde vorzubereiten.\n\nUnd was Etrigg angeht... bringt ihn zu Nathanos. Ein schneller Tod ist eine zu milde Strafe für seinen Verrat.\n\nGeht nun, {name}. Bringen wir es zu Ende.", sourceObjective = "Befehlt den Hordeanführern in Orgrimmar, die Schlachtvorbereitungen zu treffen.", completion = "So sei es. Wir haben unsere Entscheidungen gefällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[56839] = { id = 56839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mordklaue der Schreckliche", description = "<Ihr seht ein primitives Schild der Oger mit einer Warnung.>\n\nGROSSER Bär! Böse!\n\nGroßer Bär bewacht großen Ogerschatz!\n\nNach Ritual töten! Schatz schnappen, mehr Macht haben!", sourceObjective = "Besiegt Mordklaue den Schrecklichen.", completion = "<Ihr findet eine Schatztruhe, genau wie auf dem Ogerschild erwähnt!>", sourceObjectiveStatus = "unverified-source-field" }
quests[56842] = { id = 56842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondschutz", description = "Mein Stab leistet mir schon seit vielen Jahren gute Dienste. Er stand an meiner Seite und hat viele Prüfungen durchgestanden... und während ich älter werde, ertappe ich mich immer öfter dabei, dass ich mich auf ihn stütze.\n\nSeine Blüten blühen bei jedem Mondfest auf und schwelgen in Elunes Macht. Sie machen mir so viel Freude, ich wünschte, sie könnten das ganze Jahr über bleiben. Ich wüsste einen Weg... aber meine Knochen sind zu alt, um die Reise zu überstehen.\n\nVielleicht würdet Ihr die Reise für mich antreten? Ermächtigt meinen Stab im Mondlicht an den Mondbrunnen auf der ganzen Welt. Dann können meine Blüten bleiben.", sourceObjective = "Führt den Ritus des Mondes an den auf der ganzen Welt verstreuten Mondbrunnen durch. Ihr findet sie in Eschental, Teufelswald, Feralas, Mondlichtung, im Steinkrallengebirge, im Dämmerwald und am Hyjal.\n\nWenn Ihr den Segen des Monds verlöschen lasst, müsst Ihr von vorn beginnen.", progress = "Blüten gedeihen unter Elunes Licht. Sie war immer dafür bekannt, sie wertzuschätzen.", completion = "Ihr habt es geschafft! Ich spüre, dass ihm Elunes Macht innewohnt. Jetzt kann ich mich für den Rest meiner Tage an meinen Blüten erfreuen.\n\nVielleicht kann ich für Euch dasselbe tun. Falls Ihr Blumen habt, die Ihr bewahren möchtet, bringt sie mir. Ich kann Euch vielleicht dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56889] = { id = 56889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwundete Wüstenwanderer", description = "Ah, seid Ihr zurückgekehrt, um uns weitere Hilfe angedeihen zu lassen?\n\nWie Ihr seht, sind wir immer noch in Kämpfe mit diesen Kreaturen verwickelt, und es ist kein Ende in Sicht.\n\nDies ist ein Zermürbungskrieg und wir sind ganz klar im Nachteil, da die Zahl der Verletzen ständig ansteigt.\n\nBitte helft unseren Verwundeten, die Ihr innerhalb der Ruinen findet.", sourceObjective = "Heilt 6 Arbeiter der Wüstenwanderer.", completion = "Wir wissen Eure Hilfe wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56903] = { id = 56903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone des Mutes", description = "Wie ich sehe, mögt Ihr pinkfarbene Blumen. Zu schade, dass diejenigen, aus denen Eure Krone besteht, eines Tages verwelken werden.\n\nVielleicht kann ich Euch da helfen.\n\nObwohl es sich um gewöhnliche Blüten handelt, kenne ich ähnliche Blumen, die nur während des Mondfests erblühen. Wenn Ihr sie für mich holt, kann ich sie mit Elunes Macht erfüllen, damit Ihr das ganze Jahr an ihnen Freude habt.", sourceObjective = "Sammelt Blüten aus dem Immersangwald, dem Hinterland und Mulgore.", progress = "Nicht alle Blumen sind gleich. Diejenigen, die während des Mondfests blühen, haben eine ganz besondere Verbindung zu Elune.", completion = "So wunderschöne Blumen! Ich spüre Elunes Macht in ihnen.\n\nDiese Krone wírd Euch großen Mut verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56904] = { id = 56904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone des Wohlstands", description = "Eure Krone ist so farbenfroh! So hübsches Pink und Gelb und Blau... Wenn sie doch nur dauerhaft so bleiben könnte.\n\nObwohl diese Blumen hier das nicht können, kenne ich welche, denen das möglich ist!\n\nÄhnliche Blumen wie diese blühen bei jedem Mondfest. Sie haben eine ganz besondere Verbindung mit Elune, die ich dank Euch stärken kann. Holt sie für mich und wir können eine Krone herstellen, an der Ihr das ganze Jahr Freude haben werdet!", sourceObjective = "Sammelt Blüten vom Krater von Un'Goro, im Schlingendorntal und im Nördlichen Brachland.", progress = "Elune hat eine Schwäche für Blumen. Diejenigen, die während des Mondfests erblühen, sind etwas ganz Besonderes.", completion = "So eine Farbenvielfalt! Diese Blumen werden allen Freude bereiten, die sie sehen.\n\nDiese Krone wird Euch großen Reichtum bescheren.", sourceObjectiveStatus = "unverified-source-field" }
quests[56905] = { id = 56905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone der dunklen Blüten", description = "Solch triste Blumen... doch sie haben ihre ganz eigene Schönheit, findet Ihr nicht? Wenn sie doch nur dauerhaft so bleiben könnten.\n\nErlaubt mir, meine Hilfe anzubieten.\n\nBei jedem Mondfest erblühen ähnliche Blumen wie Eure überall auf der Welt. Sie haben eine ganz besondere Verbindung zu Elune... die ich ermächtigen kann. Wenn Ihr sie mir bringt, kann ich sie bewahren, damit Ihr auch dann noch Freude an ihnen habt, wenn eine gewöhnliche Blume längst gestorben wäre.", sourceObjective = "Sammelt Blüten im Dämmerwald, im Silberwald und in Desolace.", progress = "Die Blumen, die während des Mondfests blühen, haben ganz bestimmte Eigenschaften. Ich glaube, das liegt an Elunes Licht, das über ihnen wacht.", completion = "Ah, welch beruhigende Blumen. Ich spüre, wie sie einen feierlichen Frieden verströmen.\n\nDiese Krone soll Euch mit stiller Würde unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56906] = { id = 56906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone des Glücks", description = "Die Blumen erinnern mich an Elune höchstpersönlich! Ich selbst trage ähnliche das ganze Jahr über, um mich an ihre wachsame Gnade zu erinnern.\n\nVielleicht würdet Ihr das auch gerne tun?\n\nEure Krone besteht aus gewöhnlichen Blumen, die eines Tages verwelken und sterben werden. Das ist für solch zarte Schönheiten ein unseliges Schicksal, aber meine Krone besteht aus ähnlichen Blumen, bei denen ich dafür gesorgt habe, dass sie das ganze Jahr hindurch halten! Wenn Ihr mir die außergewöhnlichen Blumen bringt, die nur während des Mondfests erblühen, kann ich sie segnen, damit auch Ihr das ganze Jahr über an Eurer Krone Freude habt.", sourceObjective = "Sammelt Blüten aus Winterquell, Dun Morogh und im Vorgebirge des Hügellands.", progress = "Ganz unter uns, ich glaube, dies sind Elunes Lieblingsblumen. Sie spiegeln ihr strahlendes Mondlicht so wunderbar wider!", completion = "Ah, Blumen, die meinen gleichen. Ich spüre Elunes Ausstrahlung darin.\n\nDiese Krone wird Euch im Leben großes Glück bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56907] = { id = 56907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farblack: Nukularrot", description = "<Kram Kelada kann das sicher gut brauchen.>", sourceObjective = "Bringt den Gegenstand zu Kram Kelada.\n\nBereitgestellter Gegenstand:", completion = "Gute Farbwahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[56908] = { id = 56908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farblack: Goblingrün", description = "<Kram Kelada kann das sicher gut brauchen.>", sourceObjective = "Bringt den Gegenstand zu Kram Kelada.\n\nBereitgestellter Gegenstand:", completion = "Gute Farbwahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[56909] = { id = 56909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farblack: Argonblau", description = "<Kram Kelada kann das sicher gut brauchen.>", sourceObjective = "Bringt den Gegenstand zu Kram Kelada.\n\nBereitgestellter Gegenstand:", completion = "Gute Farbwahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[56914] = { id = 56914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Anwohner", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[56942] = { id = 56942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder auf Achse", description = "Also dann! Alle an Bord!", sourceObjective = "Fahrt mit der Kutsche.", completion = "Da kommen wir mit der Kutsche nicht durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[56955] = { id = 56955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellenräumung", description = "Das ist inakzeptabel! Die steingeborenen Rebellen haben einen Konvoi auf dem Weg zum Zehntherrn angegriffen. Er ist der lokale Ernter, der dieses Viertel kontrolliert.\n\nWir müssen irgendwie durch dieses Chaos kommen. Die Brücke auf der anderen Seite dieses Konflikts führt nach Dunkelhafen. Der Meister hat dort normalerweise einen Teil seiner Steinlegionstruppen stationiert.\n\nBahnt uns einen Weg, <Schlundgänger/Schlundgängerin>. Vernichtet jeden, der uns aufhalten könnte. Wir dürfen Graf Denathrius nicht warten lassen.", sourceObjective = "Tötet 5 steingeborene Rebellen.", completion = "Eure kämpferischen Talente sind vielversprechend. Mit ein paar Jahrhunderten mehr und ein bisschen Demut könnten wir vielleicht etwas aus Euch machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56969] = { id = 56969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Riffwandererborke", progress = "Ja? Was ist?", completion = "Wir verwenden die Riffwandererborke für viele Dinge, von Gebäuden bis Rüstungen ist alles dabei. \n\nDiese hier muss von einer der älteren stammen, sie ist wirklich enorm! Daraus lassen sich viele Dinge herstellen.\n\nIch werde diese Spende im Lager verteilen, vielen Dank!" }
quests[56970] = { id = 56970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riffwandererborke", progress = "Ja? Was ist?", completion = "Wir verwenden die Riffwandererborke für viele Dinge, von Gebäuden bis Rüstungen ist alles dabei. \n\nIch werde diese Spende im Lager verteilen, vielen Dank!" }
quests[56971] = { id = 56971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalfilet", progress = "Ja? Was ist?", completion = "Mein Lieblingsessen! Woher wusstet Ihr das?\n\nIch werde es für das Lager zubereiten. Alle werden es genießen." }
quests[56972] = { id = 56972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenrochenflügel", progress = "Ja? Was ist?", completion = "Das ist ein schöner, saftiger Flügel, den Ihr da habt.\n\nIch werde ihn zubereiten. Es ist genug für alle da." }
quests[56973] = { id = 56973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenkrabbenbein", progress = "Ja? Was ist?", completion = "Wow, das ist ja wirklich riesig. Sieht köstlich aus!\n\nIch werde ein wenig Suppe für heute Abend vorbereiten. Alle werden sie lieben." }
quests[56978] = { id = 56978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Dunkelhafen", description = "Jenseits dieser Brücke liegt der Weiler von Dunkelhafen. Er wurde von Graf Denathrius' Getreuen befestigt, also würden es die erbärmlichen Rebellen niemals wagen, diesem Ort zu nahe zu kommen.\n\nIhn zu erreichen, dürfte allerdings nicht ganz einfach werden. Ich schlage vor, ich trage die Anima, während Ihr dafür sorgt, dass uns niemand zurück in den Endmorast wirft.", sourceObjective = "Eskortiert den Obersten Kämmerer nach Dunkelhafen.", completion = "Es mag vielleicht nicht den Eindruck erwecken, aber diese Rebellion liegt in den letzten Zügen. Alle, die sich gegen den Meister auflehnen, sind Dummköpfe, die bald ein neues Ausmaß an Schmerz und Leid erfahren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[56979] = { id = 56979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Belagerung", description = "Im Chaos der Felsstürze haben Sylvanas' Saboteure es geschafft, unsere Wachen zu umgehen und Bomben an unseren Belagerungswaffen anzubringen.\n\nEinige von ihnen wurden bereits zerstört. Wir können es uns nicht leisten, noch mehr zu verlieren.", sourceObjective = "Entfernt 8 verdächtige Kisten.", completion = "Unsere Leute sind müde und unsere Ressourcen schwinden dahin. Wir brauchen jede verfügbare Waffe und jeden verfügbaren Soldaten, wenn wir die Stadt einnehmen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56980] = { id = 56980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereits unter uns", description = "Obwohl sich einige der Horde unseren Truppen angeschlossen haben, bleiben viele in Orgrimmar Sylvanas treu ergeben. Ihren Saboteuren ist es gelungen, sich unter unsere Leute zu mischen, und sie geben sich als Techniker aus. Ihre Assassinen lauern in den Schatten.\n\nHaltet alle Loyalisten auf, denen Ihr begegnet, bevor sie Schaden anrichten können.", sourceObjective = "Tötet 10 verdächtige Techniker und Assassinen der Loyalisten.", completion = "Ich wünschte, dieses Blutvergießen wäre nicht nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[56981] = { id = 56981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategischer Einsatz", description = "Saurfang meint, der Schlüssel zur Eroberung von Orgrimmar liegt darin, die verschiedenen Zugänge zu nutzen. Er war jahrelang für die Verteidigung der Stadt verantwortlich und kennt ihre verwundbaren Stellen besser als jeder andere. Wir sind sowieso schon knapp an Truppen, aber ich vertraue bei dieser Sache seinem Urteil.\n\nDonnerfels muss ebenfalls verstärkt werden, falls Sylvanas plant, dort anzugreifen, während unsere Streitkräfte hier gebunden sind.\n\nGebt diese Einsatzbefehle an unsere Offiziere weiter. Wir werden alle Tore Orgrimmars gleichzeitig überfallen und parallel Donnerfels verteidigen.", sourceObjective = "Überbringt Anduins Einsatzbefehle.", completion = "Unsere Truppen sind in Stellung. Wir warten nur noch auf den Beginn der Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[56982] = { id = 56982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren von Orgrimmar", sourceObjective = "Beginnt die Schlacht vor den Toren Orgrimmars.", completion = "Saurfang... er hat sein Leben gegeben, um die unserer Soldaten zu schützen.\n\nNiemand von uns hätte gedacht, dass er Sylvanas direkt herausfordert. Aber sie selbst vielleicht schon.\n\n<Jaina schüttelt den Kopf.> \n\nEs hilft uns nicht weiter, zu diskutieren, ob das Teil ihres Plans war oder ob sie einfach nur die Gelegenheit genutzt hat. Wir müssen uns in Acht nehmen vor ihren Machenschaften.\n\nSaurfang hat seine letzte Schlacht gewonnen. Ich weiß nicht, was aus der Horde werden wird, aber ich habe die Hoffnung, dass sie einen neuen Pfad findet, dem sie folgen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[56993] = { id = 56993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Sieges", description = "Saurfang... Wie konnte das passieren...\n\n<Jaina nimmt sich einen Moment, um sich zu sammeln.> \n\nDie Allianz kannte Hochfürst Saurfang als bitteren Feind, aber auch als unverzichtbaren Verbündeten.\n\nAnduin wird sein Andenken in Ehren halten. Ruft unsere Truppen zusammen und informiert sie darüber, was geschehen ist. Genns Soldaten wurden am westlichen Tor eingesetzt. Ihr solltet ihn dort antreffen.", sourceObjective = "Ruft die Streitkräfte der Allianz zusammen und informiert sie darüber, was geschehen ist.", completion = "In diesem Krieg gab es schon viele Tote. Hoffentlich war Saurfang der letzte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57001] = { id = 57001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Ehre" }
quests[57002] = { id = 57002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Soldat", description = "Egal, welche Zweifel er selbst gehabt haben mag, er war ein ehrenvoller Soldat.\n\nEr hat einen Bürgerkrieg innerhalb der Horde verhindert sowie die potenzielle Zerstörung der Allianz. Er hat Sylvanas' Schreckensherrschaft beendet und dabei sein Leben für viele andere gegeben. \n\nWir werden sein Opfer ehren.", sourceObjective = "Sprecht mit Jaina vor den Toren von Orgrimmar.", completion = "Wir fallen weiterhin in die alten Verhaltensweisen zurück. Misstrauen und Argwohn, Hass und Krieg... \n\nUnd trotz allem schließen wir uns zusammen und erheben uns gegen die Kräfte, die unsere Welt zerstören wollen.\n\nIch bete, dass der Tag kommt, an dem wir diesen Teufelskreis ein für alle Mal durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57003] = { id = 57003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschafft Eure eigene Stärke", description = "Dafür, dass dieser Gegenstand auf dem Meeresgrund lag, enthält er beträchtliche Macht.\n\nBringt Euer benthisches Rüstungsteil zu Leerenbinder Zorlan. Er hat es schon neugierig betrachtet.\n\nLos, macht dem Ätherischen eine kleine Freude und lasst es ihn ansehen.\n\nVielleicht bringt es uns was.", sourceObjective = "Wertet ein benthisches Rüstungsteil mithilfe von Leerenbinder Zorlan auf.", completion = "Uralte Elfenmagie und der Ozean, der Dinge mit seiner eigenen Macht erfüllt...\n\nIch würde gern behaupten, ich wäre überrascht, aber eigentlich bin ich das nicht.\n\nGut, dass Ihr diese glänzenden Freunde mitgebracht habt, um die Sache zu regeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[57004] = { id = 57004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschafft Eure eigene Stärke", description = "Die benthische Rüstung, die Ihr bei Euch habt, war zu lange im Meer verschollen.\n\nSie enthält aber immer noch Macht.\n\nLeerenbinder Sturzah kann uns damit sicher weiterhelfen.\n\nBringt Euren Fund unserem unerschrockenen ätherischen Freund und findet heraus, ob er für uns einen Nutzen hat.", sourceObjective = "Wertet ein benthisches Rüstungsteil mithilfe von Leerenbinder Sturzah auf.", completion = "Es besteht eine starke Verbindung zwischen dem Ozean und dem, was unter seinen Wogen ruht.\n\nDer leuchtende Mann kann die prismatischen Manaperlen für die Verbesserung benthischer Gegenstände verwenden.\n\nDas wird sich als höchst vorteilhaft erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57005] = { id = 57005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde werden", description = "Einige unserer mutigsten Kelfinnen haben sich freiwillig gemeldet, bei Euren Abenteuern mitzumachen, falls Ihr jemals einen Freund brauchen solltet.\n\nWie Ihr feststellen werdet, hat jeder von ihnen eigene Interessen und wird täglich verschiedene interessante Gelegenheiten auf Eurer Karte markieren.\n\nVerwendet die Muschel und wählt einen Freund aus, wenn Ihr bereit seid, Nazjatar zu erkunden!\n\nWählt weise! Ihr könnt täglich nur einen Freund auswählen.", sourceObjective = "Benutzt die Anrufmuschel, wählt einen Verbündeten und schließt 3 tägliche Quests ab.", completion = "Es tut gut, Euch hier zu wissen, {name}.\n\nDas war absolut meisterhaft. Dank Euch sind die Entfesselten ganz aufgeregt und hoffnungsvoll.\n\nUm mehr hätte ich nicht bitten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57006] = { id = 57006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiger Verbündeter", description = "Einige unserer mutigsten Ankoaner haben sich angeboten, Euch auf Eurer Expedition zu begleiten.\n\nWie Ihr feststellen werdet, hat jeder von ihnen eigene Interessen und wird täglich verschiedene interessante Gelegenheiten auf Eurer Karte markieren.\n\nBenutzt das Tiefenflammenlagerfeuer, wenn Ihr bereit seid. Wählt einen würdigen Verbündeten und erforscht zusammen, was von Nazjatar übrig ist.\n\nWählt weise! Ihr könnt täglich nur einen Freund auswählen.", sourceObjective = "Benutzt das Tiefenflammenlagerfeuer, wählt einen Verbündeten und schließt 3 tägliche Quests ab.", completion = "Mich haben Berichte erreicht, dass ihr im Feld einiges an Geschick zeigt, {name}.\n\nEs ist uns eine Ehre, Euch hier zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57007] = { id = 57007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung des Meisters", description = "Der große Graf Denathrius, seines Zeichens Meister von Revendreth und König der Venthyr, hat mich, seinen getreuen Kämmerer, gebeten, Euch sicher in seine persönlichen Gärten zu geleiten. Ein solches Privileg wurde vor Euch noch keinem Sterblichen zuteil.\n\nIhr solltet Euch zutiefst geehrt fühlen.\n\nKommt, begleitet mich in der Kutsche, und wir fahren auf die stilvolle Art zum Schloss.", sourceObjective = "Fahrt mit der Dunkelhafenkutsche.", completion = "Oh, gut, Ihr seid immer noch nicht tot?\n\nHabt Ihr gesehen, wo der Oberste Kämmerer und Knüppelfratze gelandet sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[57008] = { id = 57008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Die verfeindeten Klans", description = "Die opportunistischen Moguklans wollen das Tal erobern, während die Verteidiger sich noch von N'Zoths Angriff erholen.\n\nSie sind sowohl feige als auch töricht.\n\nZeigt ihnen, wie falsch sie liegen.", sourceObjective = "Schlagt den Angriff der Mogu im Tal der Ewigen Blüten zurück.", completion = "Diese Heuchler werden lernen, dass sie sich entweder den Rajani anschließen müssen oder zu Staub zermalmt werden.\n\nIhr habt gute Arbeit geleistet, ihnen das klarzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57009] = { id = 57009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine phägnomenale Entdeckung", description = "Tüftlermeister Oberfunks hat Eure Unterstützung bei einer wichtigen Forschungsexpedition angefordert.\n\nMit dem angesehenen Tüftlermeister zu arbeiten, wird Eure Karriere sicherlich vorantreiben. Meine hat davon außerordentlich profitiert.", sourceObjective = "Trefft Euch mit Tüftlermeister Oberfunks in Boralus.", completion = "Jetzt kann unsere Expedition beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57010] = { id = 57010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geballte Macht", description = "Herzschmiede online.\n\nLeite finale Abstimmungssequenz ein.\n\nErwarte Eingabe durch Championeinheit {name}.", sourceObjective = "Benutzt die versteinerte kohlschwarze Schuppe auf der Herzschmiede, um dem Herz von Azeroth ihre Macht zu verleihen.", progress = "Erwarte Eingabe.", completion = "So, so! Scheint, als ob das Herz von Azeroth neue Fähigkeiten hat, genau wie MUTTER gesagt hat!\n\nHaltet ein Auge offen nach mehr von diesen Essenzen. Die müssen überall in Azeroth verstreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57022] = { id = 57022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Vorstoß der Amathet" }
quests[57023] = { id = 57023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwertes Moguartefakt" }
quests[57024] = { id = 57024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte von Mechagon", description = "Ich wusste, ich hätte mit den Schmiermaxen arbeiten sollen...\n\nGazlowes Leute werden immer bezahlt und ohne dämliche Risiken. Hab gehört, die leiern wieder was Großes an...", sourceObjective = "Trefft Euch mit Gazlowe am Großen Siegel in Dazar'alor.", completion = "Also, wenn das keine angenehme Überraschung ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[57025] = { id = 57025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bitte an Revendreth", description = "Revendreths... Effizienz... im Extrahieren von Anima ist wahrscheinlich unerreicht. Vielleicht können sie helfen, wo das sonst keiner vermag.\n\nIhr müsst jedoch wissen, dass zwar manchmal Seelen aus Revendreth zurückkehren, sie jedoch nie mehr so sind wie zuvor. Es ist ein dunkles Reich, in das die Richterin jene schickt, die sie einer Chance auf Erlösung als würdig erachtet.\n\nIhr Pfad ist allerdings beschwerlich.\n\nKah-Sher wird Euch dabei helfen, das Tor nach Revendreth zu öffnen. Trefft ihn im Ring der Übertragung.", sourceObjective = "Reist nach Revendreth.", completion = "Bitte entschuldigt die aktuellen Zustände. Normalerweise wäre ein Venthyr hier, um Euch willkommen zu heißen. Es ist nur schon länger niemand mehr durch dieses Tor gekommen...\n\nAber das macht nichts, schließlich kenne ich die Begrüßungsansprache besser als eine morgendliche Auspeitschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[57026] = { id = 57026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sündenstein", description = "Nun, Ihr seid nicht wie die anderen. Eigentlich müsstet Ihr tot sein, bevor Ihr hierherkommt. Aber nun gut. Sünde bleibt Sünde und Stein bleibt Stein, wie es so schön heißt.\n\nDann wollen wir Euch mal Euren Sündenstein besorgen. Hier entlang, bitte.", sourceObjective = "Lasst Euch herumführen.", completion = "Hoffentlich haben Euch diese elenden Kreaturen nicht mit ihrem dümmlichen Gefasel gelangweilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57037] = { id = 57037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einst so süßer Klang", description = "Die Glocken! Dieser Lärm!\n\nJemand hat ihren Klang verdorben! Wenn dieser schreckliche Lärm nicht aufhört, ist es aus mit uns.\n\n<Eridia drückt Euch ihren Hammer in die Hand.>\n\nFindet die großen Vesperglocken im Tempel und schlagt sie mit meinem Hammer an. Möge der reine Klang des Hammers ihnen ihre wahre Stimme zurückgeben!\n\nIch werde auf ihr himmlisches Läuten warten. Dann treffen wir uns bei der Brücke. Und beeilt Euch!", sourceObjective = "Läutert die Vesperglocke der Reinheit und die Vesperglocke der Harmonie.", progress = "Welch bitterer Klang!", completion = "Endlich erklingen sie wieder wie früher. Das ist wie Balsam für meine Seele. Nur die lauteste Stimme ist noch nicht verstummt. Wir müssen sie zum Schweigen bringen, bevor sie alles zerstört, was uns lieb und teuer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[57039] = { id = 57039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Geister" }
quests[57043] = { id = 57043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Freunde, neue Chancen", description = "Seid gegrüßt, {name}. Ich habe eine... merkwürdige Nachricht an Euch, von einer Gruppe Goblins.\n\nEine gewisse Sassy Hartzang bittet um Eure Hilfe für eine \"richtig große Aktion\".\n\nDas Wort \"groß\" wurde mehrfach erwähnt, gefolgt von Gemurmel über Zeit und Geld.\n\nSassy wartet im Schlingendorntal auf Euch.", sourceObjective = "Sprecht mit Sassy Hartzang im Schlingendorntal.", completion = "<Sassy schnappt hörbar nach Luft.>\n\nNa, wer kommt denn da! Wisst Ihr, wie lange wir Euch gesucht haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[57045] = { id = 57045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sonderzustellung", description = "Ich freue mich, dass Ihr endlich hier seid, {name}. Ich muss eine wichtige Lieferung zustellen und vertraue keinem Goblin mehr als Euch.\n\nJa, ja, das heißt nicht viel, aber man findet dieser Tage nicht so leicht gute Leute!\n\nDieses Paket ist für Hobart Wurfhammer. Der hat eine Werkstatt in Dreckopolis, dort müsstet Ihr es hinbringen. Der arbeitet in letzter Zeit an etwas Großem!\n\nLiefert das Paket ab und lasst es um alles Geld in der Welt NICHT FALLEN!\n\nIhr habt ja keine Ahnung, wie lange ich gebraucht habe, um das Teil zu finden!", sourceObjective = "Bringt das Paket zu Hobart Wurfhammer.", progress = "Gallywix hat wirklich Nerven, mir in meinem eigenen Labor zu drohen!\n\nDer denkt, er kann mit allen machen, was er will...", completion = "Sassy Hartzang hat Euch gebeten, dieses Paket abzuliefern?\n\nAh! Das müssen die Teile sein, die ich letzten Monat bestellt habe. Endlich kann ich die letzte Testrunde meiner neusten Erfindung beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57047] = { id = 57047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einfaches Experiment", description = "Nachdem Ihr mir nun die benötigten Teile gebracht habt, kann ich meinen neusten Prototyp testen!\n\nIch nenne ihn den Panzeranzug X-52! Der wird nahezu unkaputtbar sein!\n\nGallywix hat schon immer ein Auge auf meine Erfindungen geworfen. Jetzt, wo er vom X-52 weiß, führt er bestimmt nichts Gutes im Schilde. Ich muss den Prototyp fertigstellen, bevor Gallywix ihn mir unter der Nase wegstiehlt!\n\nIch könnte bei den Experimenten wirklich etwas Hilfe brauchen.\n\nKann ich auf Euch zählen, {name}?", sourceObjective = "Unterstützt Hobart Wurfhammer.", progress = "Wir müssen den Panzeranzug X-52 fertigstellen, bevor Gallywix einen Weg findet, den Prototyp zu klauen!", completion = "Gute Arbeit, {name}! Die Experimente waren zum größten Teil ein Erfolg! Wir werden allerdings einen neuen Laborassistenten zum Testen des Sprengstoffs brauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[57048] = { id = 57048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile einkaufen", description = "Ich werde zusätzliche Bauteile benötigen, um die nächste Testphase abzuschließen.\n\nMomentan brauchen wir Thermostecker und -adapter dafür am dringendsten! Ich erkläre Euch später, wozu wir sie brauchen...\n\nKramp Schmierlunte betreibt einen Laden in der Nähe des Eingangs zur Stadt. Redet mit ihm und kriegt ihn dazu, die nötigen Teile rauszurücken.\n\nEs ist mir ganz egal, was sie kosten, sagt ihm, er soll es in Rechnung stellen! Ich habe jetzt keine Lust zu feilschen. Ich muss die Modifizierungen am Panzeranzug X-52 vorbereiten!", sourceObjective = "Sprecht mit Kramp Schmierlunte.", completion = "Thermostecker, ja? Ja, davon habe ich noch ein paar... aber die sind nicht billig!", sourceObjectiveStatus = "unverified-source-field" }
quests[57049] = { id = 57049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Seelen" }
quests[57051] = { id = 57051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulden eintreiben!", description = "Ihr braucht Thermostecker? Dann seid Ihr hier richtig.\n\nAber die gebe ich Euch nicht einfach auf Pump. Dafür gibt es schon zu viele Trottel, die mir Geld schulden. Ich bin hier überfordert. Wenn ich nicht bald mein Geld bekomme, kann ich hier demnächst dichtmachen.\n\n<Kramp Schmierlunte überlegt einen Moment.>\n\nPasst auf... Wenn Ihr diese nutzlosen Idioten mit schlagkräftigen Argumenten überzeugen könnt, mir mein Geld zu geben, dann gebe ich Euch die Thermostecker als Gegenleistung.\n\nEin besseres Angebot bekommt Ihr nirgends!", sourceObjective = "Fordert 8-mal ausstehende Schulden ein.", progress = "Habt Ihr mein Geld?", completion = "<Kramp Schmierlunte nimmt sich einen Moment Zeit, das Geld zu zählen.>\n\nEs ist alles da! Gute Arbeit, Kleiner! Die Thermostecker gehören Euch. Grüßt Wurfhammer von mir und sagt ihm, er soll eine Erfindung nach mir benennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57052] = { id = 57052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab, was Ihr braucht", description = "Abgemacht ist abgemacht, {name}. Hier sind die Thermostecker, die Ihr bestellt habt!\n\nSagt dem alten, grimmigen Wurfhammer aber, dass ich ihm nichts mehr schenken werde. Wenn er noch mehr davon braucht, sollte er lieber seinen Geldbeutel zücken.\n\nWar mir jedenfalls ein Vergnügen, mit Euch ins Geschäft zu kommen...\n\nUnd jetzt schert Euch weg!", sourceObjective = "Bringt das Paket zu Hobart Wurfhammer.", completion = "Ja! Genau die brauche ich, um die Tretminen für das bevorstehende Experiment fertigzustellen...\n\nAch, von Tretminen hatte ich nichts gesagt?\n\nIch dachte, ich hätte sie erwähnt... auch egal! Ich erkläre alles später! Wird schon schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57053] = { id = 57053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stumpfe Gewalt", description = "Nachdem wir die Thermostecker jetzt haben, sind wir bereit für den nächsten Test unseres Prototyps des Panzeranzugs X-52!\n\nLeider haben meine Laborassistenten alle gekündigt oder sind verschieden. Schade! Aber umso besser für Euch, {name}... Jetzt dürft IHR den Panzeranzug X-52 tragen!\n\nWie aufregend!\n\nDer nächste Test wird von meiner neuen mechanisierten Laborassistentin durchgeführt. Geht rüber in die Hauptwerkstatt und drückt den großen roten Knopf, um anzufangen.\n\nKeine Sorge, ich werde Euch über die integrierte Sprechanlage des X-52 Anweisungen geben.", sourceObjective = "Schließt Hobart Wurfhammers Experiment ab.", completion = "<Hobart Wurfhammer betrachtet Euch genau.>\n\nDas ist fabelhaft! Ihr erleidet aktuell mittelschwere innere Blutungen, aber der Prototyp des Panzeranzugs X-52 hat unter wiederholter massiver stumpfer Gewalteinwirkung genauso reagiert, wie ich es vorausgesagt habe.\n\nDer X-52 hat noch nicht mal einen Kratzer!", sourceObjectiveStatus = "unverified-source-field" }
quests[57058] = { id = 57058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaß mit Tretminen", description = "Der Prototyp des Panzeranzugs X-52 ist bereit für den letzten Test!\n\nWie kommt Ihr mit lauten Geräuschen und plötzlichen Erschütterungen zurecht, {name}?\n\nFür den letzten Test werden wir Euch in den Panzeranzug X-52 schnallen und durch ein Minenfeld laufen lassen!\n\nIch habe ein erfrischendes Kokosnussgetränk in der Mitte des Minenfelds platziert. Seht das Getränk als passende Belohnung dafür an, die Oase erreicht und die unvermeidlichen Explosionen auf dem Weg überlebt zu haben!", sourceObjective = "Beschafft das erfrischende Kokosnussgetränk aus dem Minenfeld.", progress = "Ballistische Tests... MAG ICH AM LIEBSTEN!", completion = "Diese Schläger zerstören meine Werkstatt! Wir müssen schnell handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[57059] = { id = 57059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst uns kämpfen!", description = "Das ist gar nicht gut, {name}! Gar nicht gut!\n\nGallywix und seine Schläger zerstören meine Werkstatt. Er hat sich aber gewaltig geschnitten, wenn er denkt, dass ich ihm den Panzeranzug X-52 kampflos überlasse!\n\nIhr müsst sofort dort runter und seine Schläger vertreiben, bevor meine Werkstatt und damit ALL MEINE ERFINDUNGEN in Rauch aufgehen!", sourceObjective = "Tötet 8 angeheuerte Halunken.", progress = "Schnell, {name}! Gallywix und seine Schläger zerstören meine Werkstatt!", completion = "Gute Arbeit mit Gallywix, {name}, aber mir ist nicht wohl bei der Sache. Wir müssen einen Käufer für den X-52 finden, bevor Gallywix zurückkommt.\n\nWer weiß, was dem als Nächstes einfällt...", sourceObjectiveStatus = "unverified-source-field" }
quests[57067] = { id = 57067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu vor den Toren", description = "Es ist so weit. Die anderen Moguklans haben das Tal der Ewigen Blüten ins Auge gefasst.\n\nSie werden es nicht erobern.\n\nEinige der Euren sind bereits am Tor, um auszuspähen, wie groß ihre Streitkräfte sind. Wenn Ihr Euch als einer solchen Mission würdig erachtet, dann trefft sie dort.", sourceObjective = "Sprecht mit Chen und Li Li Sturmbräu am Tor der Himmlischen Erhabenen.", completion = "Die Mogu sind nicht mehr in solcher Zahl aufgetaucht, seit... ich weiß nicht mehr, seit wann!\n\nWir müssen vorsichtig sein. Sie haben die ganze Ebene besetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57068] = { id = 57068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwachen mit Drachen", description = "Wir haben mit eigenen Ohren gehört, dass Mogu angreifen, aber ich wusste nicht, dass es so viele sind!\n\nEs muss einen Weg geben, sie aufzuhalten, bevor sie das Tal komplett überrennen. Schnell, lasst uns hinfliegen und herausfinden, wie viele es sind.\n\nWir haben zufällig einen Drachen, der drei Leute tragen kann. Eigentlich noch mehr, aber ich hatte ein reichhaltiges Mittagessen.", sourceObjective = "Fliegt mit Chens Drachen, um die Moguarmeen auszuspähen.", completion = "Oh nein, das war eine harte Landung. Onkel Chen kommt nicht wieder hoch! Und überall sind Mogu!\n\nSchon gut. Alles in Ordnung. Wir lassen uns etwas einfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57069] = { id = 57069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg mit den Köpfen", description = "Nun gut. Wir sitzen zwischen drei Moguarmeen fest, und Onkel Chen kann sich wegen seiner Schmerzen nicht bewegen.\n\nNoch ist es aber nicht hoffnungslos. Wir haben die Chance, die Anführer dieser Armeen auszuschalten. Vielleicht verlangsamt sie das oder lenkt sie lange genug ab, damit wir zurück zum Tor kommen!\n\nSeht zu, ob Ihr da draußen die größten und gemeinsten Mogu ausschalten könnt. Das sind die Kommandanten.", sourceObjective = "Tötet Mogukommandanten.", completion = "Gute Arbeit. Die Mogu sind ohne ihre Anführer nicht mehr so stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[57070] = { id = 57070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogumassaker", description = "Ich glaube, meine Freunde würden sagen, dass es hier \"nicht an Zielen mangelt\". Man könnte natürlich auch sagen, dass \"wir umzingelt und wahrscheinlich dem Untergang geweiht sind\".\n\nIhr wisst, was das bedeutet. Wir müssen so viele Mogu wie möglich töten! Es spielt keine Rolle, wie Ihr das tut, Ihr müsst sie nur zur Strecke bringen!", sourceObjective = "Tötet Mogu am Kun-Lai-Gipfel.", completion = "Das sind eine Menge tote Mogu. Hoffentlich hat das ihre Reihen genug ausgedünnt, dass wir von hier verschwinden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57071] = { id = 57071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Gebräu wird zurückgelassen", description = "Ich habe... Kopfschmerzen. Dafür gibt es nur eine Lösung.\n\nWir sind über einen verlassenen Brauereiwagen hinweggeflogen. Ihr müsst ihn finden und das Gebräu retten! Das sollte mir helfen, wieder auf die Beine zu kommen.\n\nAußerdem würde es Wunder für die Moral der Kämpfer im Tal bewirken, wenn wir es bergen könnten.", sourceObjective = "Findet die Fässer mit zurückgelassenem Gebräu am Kun-Lai-Gipfel.", completion = "<Das müssen die Fässer mit Gebräu sein, die Chen beim Überflug entdeckt hat.\n\nSie sind so schwer, dass Ihr sie nicht allein tragen könnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57072] = { id = 57072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yak in allen Gassen", description = "<Die Brauereifässer sind zu schwer und es sind zu viele, als dass Ihr sie allein tragen könntet.\n\nVielleicht könnt Ihr etwas oder jemanden finden, um Euch zu helfen.>", sourceObjective = "Findet etwas, womit Ihr das Gebräu zu Chen in Mogujia bringen könnt.", completion = "Was sehe ich da? Ich habt ein Yak gefunden?\n\nUnd darüber hinaus habt Ihr Gebräu gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[57074] = { id = 57074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Rücken zum Tor", description = "Welch glücklicher Zufall, dass Ihr das Gebräu gefunden habt und dazu ein Yak, um es zu tragen!\n\nAber wir dürfen nicht hierbleiben. Li Li hat mich so weit wiederhergestellt, dass ich reisefähig bin. Wir können auf dem Yak zurück zum Tor reiten und hoffen, dass die Mogu es nicht bemerken.\n\nSagt mir Bescheid, wenn Ihr abreisefertig seid.", sourceObjective = "Reitet auf Mobi mit Chen und Li Li zum Tor der Himmlischen Erhabenen.", completion = "Wir sind durchgekommen! So, was unternehmen wir jetzt gegen all die Mogu?", sourceObjectiveStatus = "unverified-source-field" }
quests[57075] = { id = 57075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssiger Mut", description = "Wir müssen etwas gegen all diese Mogu unternehmen. Wir müssen ihre Reihen lichten, bevor sie in das Tal einfallen!\n\nSo sehr Onkel Chen sein Gebräu liebt, ich glaube, wir können es besser verwenden. Springen wir auf das Yak und lehren wir die Mogu das Fürchten!", sourceObjective = "Steigt auf Mobi auf und besiegt die Moguarmeen mit der Macht des Gebräus.", completion = "All das schöne Gebräu... weg.\n\nAber sehen wir das mal von der erfreulichen Seite. Wir müssen uns jetzt mit weniger Mogu herumschlagen. Es wird Zeit, dass wir uns zurückmelden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57076] = { id = 57076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt nach Nebelhauch zurück", description = "Wir haben hier alles uns Mögliche getan. Wir wissen, dass die Mogu ganz klar eine Bedrohung sind.\n\nWenn wir das Tal verlieren, besteht die große Gefahr, dass die Schmiede in ihre Hände fällt.\n\nLasst uns nach Nebelhauch zurückkehren und den Rajani Bericht erstatten. Sie werden wissen wollen, was uns bevorsteht.", sourceObjective = "Kehrt zu Sturmsprecher Qian im Stillen Sanktum im Tal der Ewigen Blüten zurück.", completion = "Die anderen Klans wollen also mit ihren Armeen in das Tal einmarschieren?\n\nDenen werden wir zeigen, wie wahre Macht aussieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57077] = { id = 57077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käufer gesucht!", description = "Der Panzeranzug X-52 ist endlich fertig und Gallywix wurde mit Schimpf und Schande davongejagt!\n\nDas habe ich Euch zu verdanken, {name}!\n\nAber wir sind noch nicht fertig... das Beste kommt noch. Wir werden eine Auktion veranstalten und den Panzeranzug X-52 an den Höchstbietenden verkaufen!\n\nSassy Hartzang sollte eine Liste von Kaufinteressenten vorbereitet haben. Geht hinüber zu Hartzangs Versteck und sagt ihr Bescheid, dass wir bereit für die Auktion sind!", sourceObjective = "Sprecht mit Sassy Hartzang im Schlingendorntal.", completion = "Die Erfindung ist also fertig, ja? Gute Arbeit, Kleiner! Wir werden im Handumdrehen in Knete schwimmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57078] = { id = 57078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die VIP-Liste", description = "Während Ihr Wurfhammer bei seiner neuesten Erfindung geholfen habt, habe ich hart daran gearbeitet, potenzielle Käufer aufzutreiben!\n\nDas wird eine Privatauktion, also laden wir nur die hellsten Köpfe ein, die Besten der Besten, die Crème de la Crème... Ihr versteht?\n\nIch habe die potenziellen Käufer auf eine A-Liste der reichsten und hochklassigsten Goblins mit den besten Verbindungen reduziert... ohne Gallywix, versteht sich!\n\nGeht und überbringt diese Einladungen, während ich die Vorbereitungen für die Auktion abschließe!", sourceObjective = "Überbringt die Einladungen zu Wurfhammers Privatauktion.", completion = "Ihr habt die Einladungen überbracht? Sehr schön! Wir werden jegliche Hilfe brauchen können... Ich habe schlechte Neuigkeiten für Euch!\n\nHabe ich schlechte Neuigkeiten gesagt? Ich meinte RICHTIG schlechte Neuigkeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[57079] = { id = 57079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst ihn Dreckopolis fressen!", description = "Bin ich froh, Euch zu sehen! Wir haben es mit einer ganz ernsten Lage zu tun...\n\nWährend Ihr die Einladungen überbracht habt, haben Gallywix und seine Schläger Dreckopolis übernommen! Sie haben Hobart Wurfhammer als Geisel genommen und wollen, dass er ihnen den Panzeranzug X-52 übergibt!\n\nIhr müsst Gallywix aufhalten, bevor es zu spät ist!", sourceObjective = "Schließt das Dreckopolis-Szenario ab.", completion = "Der Panzeranzug X-52 ist nicht mehr reparabel... aber wenigstens ist Dreckopolis gerettet und Gallywix hat endlich bekommen, was er verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[57080] = { id = 57080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Belohnung", description = "Obwohl der Energiekern des Panzeranzugs X-52 im Kampf gegen Gallywix zerstört wurde, war die Erfindung ein voller Erfolg!\n\nIch bezweifle, dass jemand die Rechte an dem X-52 ohne funktionierenden Energiekern kaufen will, also wieso behaltet Ihr den Panzeranzug nicht einfach? Immerhin ist er echt schick!\n\nDreckopolis ist gerettet und Gallywix sitzt praktischerweise in seinem eigenen mechanischen Verprügler fest. Ich glaube, ich werde seinen sogenannten \"Vertrag\" neu verhandeln.\n\nSchließlich ist er ein \"gefesseltes Publikum\"!Ihr erlernt:", sourceObjective = "Danke für alles, was Ihr für mich getan habt, {name}! Ihr habt Dreckopolis gerettet und diesen nichtsnutzigen, betrügerischen Gallywix in die Schranken gewiesen!\n\nMein Dank ist Euch gewiss, behaltet den Panzeranzug X-52. Er steht Euch gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[57085] = { id = 57085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkter Kriegswagen" }
quests[57086] = { id = 57086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis des wahnsinnigen Magiers", description = "<In den unteren Teil dieses recht großen Juwels ist eine Inschrift eingeritzt:\n\nEigentum von Mardivas. Bei Verlust bitte zu meinem Labor zurückbringen.\n\nVielleicht lässt sich dieses Labor noch irgendwo ausfindig machen?>", sourceObjective = "Untersucht Mardivas' Labor", progress = "<Die Konstruktion der Truhe erscheint simpel, aber der Schließmechanismus summt vor arkaner Energie.>", completion = "<Das uralte Schloss öffnet sich mit einem Klicken und enthüllt den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57087] = { id = 57087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barukvernichter" }
